/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"note-level-9","number":9,"title":"Sampling","skillBand":"Textbook","duration":"From the course textbook","summary":"9.1","modules":[{"id":"note-m-9-1-101","code":"9.1","title":"9.1","blurb":"9.1","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l9-1-1","title":"9.1.1 — Mic access recap","blocks":[{"type":"step","title":"9.1.1 — Mic access recap","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.1 — Permissions and monitoring</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Grant Note microphone access so <strong>Record Sample</strong> can hear the device mic, and know where to re-enable it if iOS blocked it."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §1.1: the first time you launch Note, the app requests microphone access so you can record samples. You can also grant access later in iOS <strong>Settings → Privacy &amp; Security → Microphone</strong>. Working with Samples repeats the prompt: if iOS asks while you record, enable the microphone there."},{"type":"prose","html":"Without this permission, Drum Rack and Melodic Sampler recording will not capture the room. Cloud, MIDI, and playback of existing clips do not replace mic access. You are not turning on a Live audio track here. Pre-2.0 sampling is record-into-Drum-Rack-or-Sampler only (Manual ch.9). Audio tracks wait for Module 9.5 (2.0.1)."},{"type":"prose","html":"If you denied the first-launch dialog, Note will not keep asking forever. Use the iOS path. After you flip the toggle, return to Note and try <strong>Record Sample</strong> again."},{"type":"prose","html":"Troubleshooting Audio Output on Note: iOS <strong>Sound Recognition</strong> (Settings → Accessibility → Hearing) can interfere with recording or playback. If the mic is granted and you still get silence, turn Sound Recognition off."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["On the iPhone or iPad, open iOS <strong>Settings → Privacy &amp; Security → Microphone</strong>.","Confirm <strong>Note</strong> is enabled. If it is off, turn it on.","Open Note, open a Drum Rack or Sampler, and look for <strong>Record Sample</strong> / <strong>Record</strong>.","If iOS prompts again, allow the microphone.","If recording is still silent, disable <strong>Sound Recognition</strong> (Accessibility → Hearing) and retry.","Recite the path: <strong>Settings → Privacy &amp; Security → Microphone → Note</strong>."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["When does Note first ask for the mic? <strong>Answer:</strong> The first time you launch the app (Manual §1.1).","Where do you re-grant access? <strong>Answer:</strong> iOS <strong>Settings → Privacy &amp; Security → Microphone</strong>.","Can an AUv3 recorder replace this permission? <strong>Answer:</strong> No. AUv3 is not available in Note."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §1.1 Setup (microphone access)","Working with Samples in Note (enable the device microphone in iOS Settings)","Troubleshooting Audio Output on Note (Sound Recognition)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Toggle Note’s mic permission off and on once (if you can do so safely), then record a one-second test into an empty pad so you know the path works."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-1-1</code></em>"}]}],"minutes":8},{"id":"note-l9-1-2","title":"9.1.2 — Orange mic icon expected","blocks":[{"type":"step","title":"9.1.2 — Orange mic icon expected","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.1 — Permissions and monitoring</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Treat the iOS orange microphone indicator as normal while Note is open, not as a bug."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"FAQ: “When I’m using Note, an orange microphone icon appears in iOS. Is this expected?” Yes. “Note accesses the microphone of your device by default. This is indicated by the orange microphone icon displayed in iOS, which is expected.”"},{"type":"prose","html":"The orange dot or icon is iOS hardware-in-use status. It does not mean you are uploading the room to Cloud. Cloud transfers Sets you choose to upload (8 Sets max, transfer not backup). It does not mean a clip is recording. Recording into a pad still requires <strong>Record Sample</strong> and the red square (ch.9)."},{"type":"prose","html":"You will see the indicator even when you are only playing pads, because the app holds mic access by default. Do not revoke the permission to hide the icon or you break 9.1.1. If you need to confirm privacy text, Manual §2.6 Privacy &amp; Legal is in App Settings — that page is not a mic toggle."},{"type":"prose","html":"Screen-awake behavior (RN 1.0.15) is separate: Note keeps the screen on in the foreground. The orange icon is about the microphone, not the display."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open Note and leave it in the foreground.","Find the iOS orange microphone indicator.","Play a clip without tapping <strong>Record Sample</strong>. Confirm the icon can still be present.","Start a short pad recording. Confirm the in-app red square is the record state, not the orange iOS icon.","Leave Note. Confirm the orange indicator clears when another app is not using the mic.","Recite: orange icon = expected; Note holds the mic by default."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Is the orange microphone icon a problem? <strong>Answer:</strong> No. FAQ: it is expected because Note accesses the mic by default.","Does the orange icon mean a sample is being recorded? <strong>Answer:</strong> No. Recording uses <strong>Record Sample</strong> and the red square in Sample View.","Should you disable mic access to hide the icon? <strong>Answer:</strong> No. You need that permission to sample."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (orange microphone icon expected)","Ableton Note Manual ch.9 (Record Sample / red square)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write one sentence you could tell a collaborator: the orange icon is iOS showing Note has mic access, not a Cloud leak."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-1-2</code></em>"}]}],"minutes":8},{"id":"note-l9-1-3","title":"9.1.3 — Monitor when headphones connected","blocks":[{"type":"step","title":"9.1.3 — Monitor when headphones connected","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.1 — Permissions and monitoring</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Use the pre-2.x <strong>Monitor Audio Input</strong> preference so you hear the input while recording into Drum or Melodic Sampler when headphones are connected."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §2.4.5.2: enable <strong>Monitor Audio Input</strong> “to automatically monitor audio input when headphones are connected to your device. This lets you hear the input signal while recording into the Drum or Melodic Sampler.” RN 1.0.15 added that option. On pre-2.0 Note it lives in <strong>App Settings → Preferences</strong> (Other)."},{"type":"prose","html":"This lesson is the pre-2.x location. RN 2.0.1 <strong>removed</strong> the Settings toggle because monitoring is managed inside the Set (9.1.4). If <strong>Settings → Help</strong> shows 2.0.1+, do not hunt for this preference. Use the track / empty-sampler controls in the next lesson."},{"type":"prose","html":"Prefer wired headphones. FAQ / Bluetooth KB: Bluetooth latency is 34–200 ms; wired is about 5–10 ms. Monitoring through AirPods makes timing harder when you record hits."},{"type":"prose","html":"Monitoring is not recording. You still tap <strong>Record Sample</strong>. Sound Recognition can still interfere (Troubleshooting Audio Output on Note)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Read <strong>Settings → Help</strong>. If you are on 2.0.1+, skip to 9.1.4.","Connect headphones (wired if you have them).","Open <strong>App Settings → Preferences</strong> and enable <strong>Monitor Audio Input</strong>.","Open an empty Drum pad or Sampler and speak or tap near the mic. Confirm you hear input.","Record a one-second test. Confirm monitor and recording are both working.","Recite: pre-2.x monitor toggle lives in Preferences and requires headphones."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What does <strong>Monitor Audio Input</strong> do? <strong>Answer:</strong> Automatically monitors audio input when headphones are connected, so you hear the signal while recording into Drum or Melodic Sampler.","Where is that toggle before Note 2.x? <strong>Answer:</strong> App Settings → Preferences (Manual §2.4.5.2 / RN 1.0.15).","What happened to the toggle in 2.0.1? <strong>Answer:</strong> It was removed. Monitoring is managed from within the Set."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §2.4.5.2 Monitor Audio Input","Note Release Notes 1.0.15 (headphones monitoring); 2.0.1 (toggle removed)","Bluetooth Headphones and Latency in Note (wired 5–10 ms; BT 34–200 ms)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Record one pad with monitoring on and headphones connected. If you are already on 2.x, write that the Settings toggle is gone and continue."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-1-3</code></em>"}]}],"minutes":8},{"id":"note-l9-1-4","title":"9.1.4 — 2.x monitoring from track/empty sampler views","blocks":[{"type":"step","title":"9.1.4 — 2.x monitoring from track/empty sampler views","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.1 — Permissions and monitoring</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"On Note 2.0.1+, enable input monitoring from the audio-track view or the Session track menu, and use the same empty-sampler view as an empty audio clip."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1 Input Monitoring:"},{"type":"list","items":["Audio inputs can be monitored and processed through audio tracks.","Enable monitoring from the <strong>audio track view</strong> or from the <strong>track context menu in Session View</strong>.","Monitoring is <strong>exclusive</strong> and <strong>fixed</strong> to the track you enable it on.","A track-icon indicator shows the input signal in real time.","The empty sampler view was updated with the same features as the empty audio clip.","The <strong>Input Monitoring</strong> toggle was <strong>removed</strong> from Settings."],"ordered":false},{"type":"prose","html":"If you are below 2.0.1, this lesson is a skip (use 9.1.3). Do not look for the old Preferences switch."},{"type":"prose","html":"“Exclusive” means you monitor one track at a time. Turn it on where you will record. The empty sampler view matching the empty audio clip is how you monitor before you drop a sample into Drum Rack or Melodic Sampler."},{"type":"prose","html":"Processing through audio tracks is a 2.x audio-track fact (Module 9.5). Sampler recording still exists. Do not blend warp rules yet (9.5.4–9.5.5)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 2.0.1. If not, skip.","Confirm <strong>Input Monitoring</strong> is gone from Settings.","Open Session View. Long-press or open the track context menu on the track you will record.","Enable monitoring there, or open the audio-track / empty-sampler view and enable it.","Watch the track-icon input indicator. Speak into the mic.","Enable monitoring on a second track and confirm it is exclusive (the first track no longer holds it)."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where do you enable monitoring in 2.0.1+? <strong>Answer:</strong> Audio track view, or the track context menu in Session View.","Is monitoring still a Settings toggle? <strong>Answer:</strong> No. RN 2.0.1 removed it.","Can two tracks monitor at once? <strong>Answer:</strong> No. Monitoring is exclusive and fixed to the track it is enabled on."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 Input Monitoring; empty sampler view update"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Monitor an empty sampler pad and an audio track (if you already have one) for one minute each. Leave monitoring on only the track you will record next."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-1-4</code></em>"}]}],"minutes":8},{"id":"note-l9-1-5","title":"9.1.5 — External interface inputs","blocks":[{"type":"step","title":"9.1.5 — External interface inputs","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.1 — Permissions and monitoring</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"On Note 2.0.1+, choose an input source from the built-in microphones or a connected external device via the microphone button on empty audio-clip and sampler views."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1 Audio Interface Support: “Input sources can now be selected from the built-in microphones and external connected devices.” Access that chooser “from the microphone button in the empty audio clip and sampler views.”"},{"type":"prose","html":"This is a 2.x fact. The local manual’s sampling chapter records from the device microphone (and resample). It does not document an interface picker. Below 2.0.1, {type:'gap'} no official extract describes selecting a USB interface input inside Note. Skip the picker and use the built-in mic."},{"type":"prose","html":"{type:'gap'} Release notes do not list supported interfaces, channel counts, or phantom power. Use a class-compliant device if you have one, and select whatever sources the microphone button actually shows. MIDI class-compliance (FAQ) is a different feature."},{"type":"prose","html":"Prefer wired monitoring (9.1.3–9.1.4). Troubleshooting: Sound Recognition can still interrupt recording."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 2.0.1. If not, write a gap line and use the built-in mic.","Open an empty audio clip or empty sampler view.","Tap the <strong>microphone</strong> button.","Select the built-in microphone. Record a one-second test.","If an external interface is connected, select it from the same menu and record a second test.","Switch back to the built-in mic from memory."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where do you pick the input in 2.0.1+? <strong>Answer:</strong> The microphone button in the empty audio-clip and sampler views.","What sources does the RN name? <strong>Answer:</strong> Built-in microphones and external connected devices.","Is this picker in the local manual? <strong>Answer:</strong> No. It is RN 2.0.1 only."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 Audio Interface Support","Ableton Note Manual ch.9 (device mic / resample — no interface picker)","Troubleshooting Audio Output on Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write which source you will use for 9.2 recordings: built-in or interface. Stay on that source for the next module."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-1-5</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-9-2-102","code":"9.2","title":"9.2","blurb":"9.2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l9-2-1","title":"9.2.1 — Empty Drum pad record","blocks":[{"type":"step","title":"9.2.1 — Empty Drum pad record","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.2 — Record into samplers</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Record a new audio file directly into an empty Drum Rack pad and stop it with the red square or the red pad."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual ch.9: samples go on tracks that contain a Drum Rack or a Sampler. Add a Drum Rack, select the pad, then tap <strong>Record Sample</strong> (manual) / <strong>Record</strong> (Working with Samples). The pad turns red. A small red square appears in the top right of the waveform window. Stop by tapping that red square or the red pad. Working with Samples: if iOS prompts, enable the microphone."},{"type":"prose","html":"While recording onto a pad, tap a different pad to start recording onto the newly selected one. Use that to grab several hits without stopping the whole flow."},{"type":"prose","html":"After stop, Note “automatically cropped [the sample] to start playing at the first detected transient.” Drag the waveform left or right to change the start. Pinch to zoom. Drag up or down to set gain between <strong>+24</strong> and <strong>−70 dB</strong>. RN 1.0.6: when the waveform tab is empty, that tab is selected by default."},{"type":"prose","html":"This is not an audio track (9.5). It is a one-shot (or longer hit) inside a Drum Sampler pad. Warp-not-available on this path is the FAQ rule (9.5.5)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Load a Drum Rack (Templates has empty racks at the top — RN 1.2).","Select an empty pad. Tap <strong>Record Sample</strong> / <strong>Record</strong>.","Make one hit into the mic. Tap the red square or the red pad to stop.","Play the pad. If the start is late or early, drag the waveform.","Tap a second empty pad while you still want to record, and grab a second hit.","Recite: select pad → Record → red square/pad to stop → first transient crop."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How do you stop a pad recording? <strong>Answer:</strong> Tap the red square in the waveform window or the pad that turned red.","What does Note do to the start automatically? <strong>Answer:</strong> Crops to the first detected transient.","Can you jump to another pad while recording? <strong>Answer:</strong> Yes. Tap a different pad to start recording there."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual ch.9 Using Samples","Working with Samples in Note (Recording samples)","Note Release Notes 1.0.6 (empty waveform tab selected by default)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Record kick, snare, and hat candidates onto three pads. Do not import files yet."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-2-1</code></em>"}]}],"minutes":8},{"id":"note-l9-2-2","title":"9.2.2 — Empty Melodic Sampler record","blocks":[{"type":"step","title":"9.2.2 — Empty Melodic Sampler record","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.2 — Record into samplers</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Record a sample into Melodic Sampler and play it at original pitch on the <strong>C3</strong> pad, then across the scale."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual ch.9: adding samples to Sampler “works in a similar way: you can either load or record samples into the device.” Working with Samples: in Sampler, tap <strong>Record Sample</strong>. Stop with the red square. The same mic permission and orange-icon rules apply."},{"type":"prose","html":"Pitch rule, official: “Sampler plays audio files at their original pitch on the <strong>C3</strong> pad, otherwise the sample will be transposed across the scale accordingly depending on which note you tap.” If <strong>In Key</strong> is on (Set Settings), pads snap to the Set’s scale. If <strong>In Key</strong> is off, the layout is chromatic (Keys = piano). RN 2.0.1: piano layout is the default for new melodic tracks; C Major is the default key."},{"type":"prose","html":"FAQ: on this sampler path, <strong>Transpose</strong> also changes playback speed. Warping is not available here. Do not expect a 2.x audio-track warp (that is 9.5.4)."},{"type":"prose","html":"Save if you want the take in other Sets: Sample Options <strong>Save Sample</strong> writes to Recordings → Melodic Sampler (manual §9.2). Unsaved recordings live under <strong>Libraries → Current Set → Recordings</strong>."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Load Melodic Sampler (empty template if you have it).","Tap <strong>Record Sample</strong>. Record a note, voice, or object tone. Tap the red square.","Play the <strong>C3</strong> pad. That is original pitch.","Play pads above and below. Hear the transposition.","Toggle <strong>In Key</strong> if you want the sample snapped to the Set’s scale.","From memory: C3 = original pitch; other pads transpose; speed couples on this path."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which pad plays the sample at original pitch? <strong>Answer:</strong> C3.","How do you start the recording in Sampler? <strong>Answer:</strong> Tap <strong>Record Sample</strong>.","Does Transpose on Sampler keep duration constant? <strong>Answer:</strong> No. FAQ: transpose also affects playback speed. Warp is not on this path."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual ch.9 (record into Sampler; C3 original pitch)","Working with Samples in Note","Note FAQ (warp not available; transpose couples speed)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Record one pitched sound. Play a three-note phrase from C3. Leave it loaded for 9.2.6’s contrast with a resampled Drift riff."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-2-2</code></em>"}]}],"minutes":8},{"id":"note-l9-2-3","title":"9.2.3 — Resampling / Recording toggle in Sample Options","blocks":[{"type":"step","title":"9.2.3 — Resampling / Recording toggle in Sample Options","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.2 — Record into samplers</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Find the <strong>Resampling / Recording</strong> switch in Sample Options (1.5.2+) and know it is the menu form of the long-press mic toggle."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Two official ways to switch the record source:"},{"type":"list","items":["Manual §9.1: long-press the <strong>microphone</strong> icon in Sample View of a Drum Rack pad or Sampler to access <strong>Resample Output</strong>. Long-press the Resample Output icon again to return to <strong>Microphone Input</strong>.","RN 1.5.2: Sample Options gained a <strong>Resampling / Recording</strong> toggle. The same release moved Sample Options to <strong>…</strong> on each sample."],"ordered":true},{"type":"prose","html":"Use whichever your version shows. Below 1.5.2, use the long-press only. Resample still requires other clips playing (manual §9.1). Recording still requires mic access."},{"type":"prose","html":"This lesson is only the toggle. The next lesson performs a resample. Do not confuse Drum Sampler <strong>FX Type</strong> (Stretch, Loop, and so on) with resample. FX Type is playback on the pad. Resample records Note’s output into a new file."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open a Drum pad or Sampler that already has a sample, or an empty Sample View.","If version ≥ 1.5.2, tap <strong>…</strong> (Sample Options) and find <strong>Resampling / Recording</strong>.","Also long-press the microphone icon (manual path). Confirm you can reach <strong>Resample Output</strong>.","Switch back to <strong>Microphone Input</strong> / <strong>Recording</strong>.","If <strong>…</strong> is missing, stay on the long-press path and write a 1.5.2 version note.","Recite both paths: long-press mic, and (1.5.2+) Sample Options toggle."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What does long-pressing the mic icon do? <strong>Answer:</strong> Opens <strong>Resample Output</strong>; long-press again for <strong>Microphone Input</strong>.","What did RN 1.5.2 add? <strong>Answer:</strong> A Resampling/Recording toggle in Sample Options, and <strong>…</strong> access.","Can you resample with no other clips playing? <strong>Answer:</strong> Manual §9.1 frames resample as available when other clips are playing."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §9.1 Resampling Note’s Output","Note Release Notes 1.5.2 (Resampling/Recording toggle; Sample Options via …)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Switch to Resample Output and back to Microphone Input once without recording. Leave the source on Microphone for 9.2.5."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-2-3</code></em>"}]}],"minutes":8},{"id":"note-l9-2-4","title":"9.2.4 — Resample Note’s output","blocks":[{"type":"step","title":"9.2.4 — Resample Note’s output","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.2 — Record into samplers</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Record the audio that Note is already playing into a Drum pad or Melodic Sampler using <strong>Resample Output</strong>."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §9.1: besides recording the mic, you can resample Note’s output. “If other clips are playing in a Set, you can long-press on the microphone icon in the Sample View of a Drum Rack pad or Sampler device to access the <strong>Resample Output</strong> recording option.” Then record. Tap <strong>Stop</strong> when finished to add the audio file to the pad or Sampler. Long-press again to return to <strong>Microphone Input</strong>."},{"type":"prose","html":"Working with Samples adds: you see the waveform of the audio being recorded and can set the desired volume of the recording. Stop with the red square."},{"type":"prose","html":"Requirements you can defend: clips must be playing; destination is a Drum pad or Sampler, not a mystery third recorder. This prints a new sample. It does not bounce the Set to disk (that is Export Audio: WAV 48 kHz 16-bit or M4A 48 kHz 32-bit). Resample is a creative print — freeze a Drift + FX performance into a playable sample."},{"type":"prose","html":"On 2.0.1 audio tracks you can also record loops (9.5). This lesson stays on the sampler path."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Launch at least one clip so the Set is making sound.","Open an empty Drum pad or Sampler Sample View.","Long-press the microphone icon and choose <strong>Resample Output</strong> (or the 1.5.2 Sample Options toggle).","Press <strong>Record Sample</strong>. Watch the waveform. Set recording volume if the view offers it.","Tap the red square / Stop. Play the new sample.","Long-press again and return to <strong>Microphone Input</strong>."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What must already be happening to resample? <strong>Answer:</strong> Other clips playing in the Set (Manual §9.1).","How do you enter Resample Output on the manual path? <strong>Answer:</strong> Long-press the microphone icon in Sample View.","Is resample the same as Export Audio? <strong>Answer:</strong> No. Resample writes a sample into a pad or Sampler. Export Audio renders scenes to a file."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §9.1 Resampling Note’s Output","Working with Samples in Note (Resampling audio)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Resample two bars of your current Set onto an empty pad. Play that pad as a new shot."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-2-4</code></em>"}]}],"minutes":8},{"id":"note-l9-2-5","title":"9.2.5 — environmental hit kit","blocks":[{"type":"step","title":"9.2.5 — environmental hit kit","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.2 — Record into samplers</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Record a small kit of environmental hits onto Drum Rack pads and play a two-bar beat from those takes."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Note’s pitch is sampling the environment (Manual §1; FAQ). This lab is that verb, not an import. Use the empty-pad record path from 9.2.1. Beatmaking extract: kick, snare, hat are the usual beat roles — you may assign a table hit to kick, a clap or book snap to snare, a key jingle to hat. Working title and a limitation help (Level 0.4): “three objects, no factory kit.”"},{"type":"prose","html":"Each pad: <strong>Record Sample</strong> → hit → red square. Note crops to the first transient; drag the waveform if the start is late. Gain range is +24 to −70 dB. If two hits overlap when you play fast, enable <strong>Choke Sample</strong> later (9.4.10). One choke group per Drum Rack."},{"type":"prose","html":"Monitor with headphones if you can (9.1.3 / 9.1.4). Orange mic icon is expected. Do not resample for this lab. Do not use a 2.x audio track."},{"type":"prose","html":"Save keepers: <strong>Save Sample</strong> stores recorded Drum hits under <strong>Libraries → User Library → Recordings → Drum Sampler</strong>. Unsaved takes stay in <strong>Current Set → Recordings</strong>."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Create or open a Set. Load an empty Drum Rack.","Record three to five environmental hits onto separate pads (body, snap, tick, plus optional perc).","Adjust start and gain on each pad so the transient is immediate.","Capture a two-bar beat (Fixed Length 2 bars, or play then Capture).","If a hit is late, recapture that pad only.","Play the beat from memory and name which object is kick/snare/hat."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where do these samples live if you do not save them? <strong>Answer:</strong> <strong>Libraries → Current Set → Recordings</strong>.","Where do saved Drum recordings go? <strong>Answer:</strong> <strong>Libraries → User Library → Recordings → Drum Sampler</strong>.","Why not import for this lab? <strong>Answer:</strong> The lab is environmental recording, which is one of Note’s four operations."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §1; ch.9; §9.2 Save Sample","Working with Samples in Note (recording; storage paths)","Beatmaking with Ableton Note (kick/snare/hat roles; limitation)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Keep the three best pads. Mute factory kit tracks. This kit feeds later slice/import labs only as a contrast — do not replace it yet."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-2-5</code></em>"}]}],"minutes":8},{"id":"note-l9-2-6","title":"9.2.6 — resample a Drift riff into Melodic Sampler","blocks":[{"type":"step","title":"9.2.6 — resample a Drift riff into Melodic Sampler","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.2 — Record into samplers</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Print a playing Drift clip, including its FX, into Melodic Sampler so you can replay the riff as a sample."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Resample (9.2.4) becomes useful when a synth performance plus <strong>FX1</strong>/<strong>FX2</strong> is the sound you want to play chromatically. Launch the Drift clip, open an empty Melodic Sampler, long-press the mic to <strong>Resample Output</strong>, record, stop. The new file is a sample. C3 is original pitch (Manual ch.9). Other pads transpose — and on this path, transpose couples speed (FAQ)."},{"type":"prose","html":"Why bother: you can choke CPU-like complexity by printing, or freeze a filter automation pass as a one-shot texture. You do not get independent time and pitch on this sample (that is 2.0.1 audio tracks). If you need a warped loop, wait for 9.5."},{"type":"prose","html":"Save the take to <strong>Recordings → Melodic Sampler</strong> if you want it in other Sets. The Drift clip can stay in the Set; resample does not delete it."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Create a short Drift riff clip with the FX pair you liked in Level 8.","Add or select a Melodic Sampler track. Open Sample View.","Launch the Drift clip. Switch the Sampler to <strong>Resample Output</strong>.","Record at least one loop. Stop with the red square.","Play C3, then a higher pad. Hear pitch and speed change together.","Mute the Drift track and play the phrase from the Sampler pads."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What did you record? <strong>Answer:</strong> Note’s output — the playing Drift (and its effects) — into Sampler.","Which pad is original pitch? <strong>Answer:</strong> C3.","Can you retune the resampled riff without changing its length? <strong>Answer:</strong> Not on this path. FAQ: transpose affects speed; warp is not available in Sampler/Drum Rack."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §9.1; ch.9 C3 rule","Working with Samples in Note","Note FAQ (warp / transpose on sampler path)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Keep either the live Drift or the printed Sampler version, not both in the mix. Write which one still serves the working title."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-2-6</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-9-3-103","code":"9.3","title":"9.3","blurb":"9.3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l9-3-1","title":"9.3.1 — Formats: WAV, AIFF, M4A, MP3 → WAV","blocks":[{"type":"step","title":"9.3.1 — Formats: WAV, AIFF, M4A, MP3 → WAV","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Import only the formats Note documents, and expect M4A and MP3 to convert to WAV on the way in."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Two official lists, slightly different:"},{"type":"list","items":["Manual ch.9: WAV, AIFF, and M4A. “M4A files will be converted to WAV files as soon as they are imported.”","FAQ and Working with Samples: WAV, AIFF, M4A, <strong>and MP3</strong>. “M4A and MP3 files are converted to WAV upon import.”"],"ordered":false},{"type":"prose","html":"Teach the wider FAQ/KB list. The local manual omits MP3. {type:'gap'} If an old manual-only build rejected MP3, that conflict is why you also keep the FAQ line. Current KB/FAQ include MP3."},{"type":"prose","html":"Working with Samples warning: some sharing services convert files to a non-supported format such as a different M4A flavor; on some platforms MP3s display as WAV. If a file will not open, check the real type."},{"type":"prose","html":"Size limit: RN 1.0.6 — samples larger than 100 MB cannot be imported or selected; Cloud warns around 100 MB (9.3.11). Uppercase <code>.WAV</code> failed historically and was fixed in 1.0.15 (9.3.12)."},{"type":"prose","html":"Imported audio still lands in Drum Rack or Sampler (manual). 2.x audio tracks can load samples too (9.5.6) — version-gate that."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Pick a small WAV or AIFF, and one M4A or MP3 if you have it.","Share or AirDrop into Note (9.3.2–9.3.3) or place it in the Imported folder (9.3.4).","Load the file onto a pad or Sampler.","If it was M4A/MP3, treat the copy inside Note as WAV.","If it fails, check format and size (100 MB).","Recite the four import types and the convert-to-WAV rule."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which formats do FAQ and Working with Samples allow? <strong>Answer:</strong> WAV, AIFF, M4A, and MP3.","What happens to M4A and MP3? <strong>Answer:</strong> They convert to WAV on import.","What does the local manual omit? <strong>Answer:</strong> MP3. Use the FAQ/KB list."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual ch.9 (WAV, AIFF, M4A → WAV)","Note FAQ; Working with Samples in Note (adds MP3)","Note Release Notes 1.0.6 (100 MB)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Import one compressed file (M4A or MP3) and one WAV. Load both onto pads. Confirm both play."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-1</code></em>"}]}],"minutes":8},{"id":"note-l9-3-2","title":"9.3.2 — AirDrop import","blocks":[{"type":"step","title":"9.3.2 — AirDrop import","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"AirDrop an audio file into Note and accept the import prompts so it appears in the User Library."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual ch.9: import with AirDrop or Share from other apps. Working with Samples, AirDrop steps:"},{"type":"list","items":["On the source device, open AirDrop and drag in the audio file.","When asked whether to share the filename, press <strong>Accept</strong>.","On the iOS device, when asked to select an app, choose <strong>Ableton Note</strong>.","When Note opens, choose <strong>Yes</strong> to import the sample."],"ordered":true},{"type":"prose","html":"Supported types: WAV, AIFF, M4A, MP3 (M4A/MP3 → WAV). RN 1.0.15 fixed AirDrop imports that only appeared after re-entering the folder in the browser — current builds should show the file without that extra dance. If you are on a pre-1.0.15 Note, leave the folder and go back in."},{"type":"prose","html":"The file lands in <strong>Libraries → User Library → Imported</strong> (in-app) and <strong>Files → On My iPhone/iPad → Ableton Note → User Library → Imported</strong> (Files app). Then <strong>Load Sample</strong> onto a pad or Sampler."},{"type":"prose","html":"AirDrop of a <strong>.ablbundle</strong> is a Set transfer (Level 1), not this lesson."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["From a Mac or another iOS device, AirDrop a short WAV/AIFF/M4A/MP3 to this device.","<strong>Accept</strong> the share.","Choose <strong>Ableton Note</strong> as the app.","In Note, tap <strong>Yes</strong> to import.","Open a Drum pad → <strong>Load Sample</strong> → <strong>Libraries → User Library → Imported</strong>.","Repeat the path from memory with a second file if you have one."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which app must you pick on the receiving device? <strong>Answer:</strong> Ableton Note.","What do you tap when Note opens? <strong>Answer:</strong> <strong>Yes</strong> to import the sample.","Where does the file live after import? <strong>Answer:</strong> User Library → Imported (in Note and in Files)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual ch.9","Working with Samples in Note (AirDrop steps)","Note Release Notes 1.0.15 (AirDrop import browser refresh fix)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"AirDrop one hit you will use on the 9.3.14 kit. Do not load a 100 MB file."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-2</code></em>"}]}],"minutes":8},{"id":"note-l9-3-3","title":"9.3.3 — Share from other apps","blocks":[{"type":"step","title":"9.3.3 — Share from other apps","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Use another app’s <strong>Share</strong> / <strong>Share to…</strong> sheet and pick Note so the audio is imported."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual ch.9 and FAQ: import via AirDrop <strong>or</strong> Share from other apps. Working with Samples: “Share to…” from other apps. Voice Memos, Files, Mail, and similar iOS share sheets are the usual sources. Pick <strong>Ableton Note</strong>, then confirm the import if Note asks."},{"type":"prose","html":"Same format rules as 9.3.1. Same warning: a share service may convert the file to something Note rejects, or label an MP3 as WAV. If Note cannot open it, check the real type."},{"type":"prose","html":"This is not <strong>Share To…</strong> of a Set (<code>.ablbundle</code>). That exports a project. Here another app shares <em>audio into</em> Note."},{"type":"prose","html":"Video shares are 9.3.5 (RN 1.0.15: select a video, crop its audio, import via the Imported folder). If you share a video, use that lesson’s crop path rather than expecting a silent video file to play as a pad."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open Voice Memos or Files and select a short supported audio file.","Open the iOS <strong>Share</strong> sheet.","Choose <strong>Ableton Note</strong>.","Confirm the import in Note.","Load the file from <strong>Libraries → User Library → Imported</strong>.","Recite: Share from the other app → Note → Yes/import → Imported folder."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What official import methods sit beside AirDrop? <strong>Answer:</strong> Share / Share to… from other apps.","What if the file still will not open? <strong>Answer:</strong> Check that it is WAV, AIFF, M4A, or MP3, under 100 MB, and not a false type.","Is this the same as sharing a Set? <strong>Answer:</strong> No. Set Share To… creates an <code>.ablbundle</code>."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual ch.9","Note FAQ (AirDrop or Share; formats)","Working with Samples in Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Share one Voice Memo (or Files audio) into Note and play it on a pad."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-3</code></em>"}]}],"minutes":8},{"id":"note-l9-3-4","title":"9.3.4 — Files app Imported folder","blocks":[{"type":"step","title":"9.3.4 — Files app Imported folder","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Find imported audio on disk and in Note’s browser so you can load it without AirDrop-ing again."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Working with Samples, storage:"},{"type":"list","items":["On disk: <strong>Files → On My iPhone / iPad → Ableton Note → User Library → Imported</strong>","In Note: <strong>Libraries → User Library → Imported</strong>"],"ordered":false},{"type":"prose","html":"Recordings (not this folder) live in <strong>User Library → Recordings</strong> (Drum Sampler vs Melodic Sampler subfolders) or <strong>Libraries → Current Set → Recordings</strong> if unsaved."},{"type":"prose","html":"RN 1.0.12: you can import samples and create folders in the <strong>Imported</strong> folder; User Samples migrated to User Library. Use Files to drop a WAV into <strong>Imported</strong>, then load it from the in-app browser. RN 1.0.15: some AirDrop imports only showed after you re-entered the folder — leave and go back in if a file is invisible on an old build."},{"type":"prose","html":"Do not delete the Ableton Note folder to “clean up” (Level 1: back up that folder before deleting the app). Cloud is not this folder."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open the iOS <strong>Files</strong> app.","Go to <strong>On My iPhone/iPad → Ableton Note → User Library → Imported</strong>.","Confirm a file you already imported is there (or copy a small WAV in).","In Note, on a pad, tap <strong>Load Sample</strong>.","Navigate <strong>Libraries → User Library → Imported</strong> and load it.","Recite both paths from memory."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is the Files path for imports? <strong>Answer:</strong> On My iPhone/iPad → Ableton Note → User Library → Imported.","What is the in-app path? <strong>Answer:</strong> Libraries → User Library → Imported.","Where are unsaved recordings from this Set? <strong>Answer:</strong> Libraries → Current Set → Recordings."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Working with Samples in Note (Sample storage locations)","Note Release Notes 1.0.12 (Imported folder; User Library migration); 1.0.15 (browser refresh after AirDrop)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Put one extra one-shot in the Imported folder via Files and load it onto an empty pad."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-4</code></em>"}]}],"minutes":8},{"id":"note-l9-3-5","title":"9.3.5 — Video select + crop audio","blocks":[{"type":"step","title":"9.3.5 — Video select + crop audio","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Import audio from a video by selecting the video, cropping the audio, and taking the result from the <strong>Imported</strong> folder (RN 1.0.15)."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.0.15: “Video-Audio Import: Added option to select a video, crop its audio and then import it (via <strong>Imported</strong> folder).” The syllabus title says 1.0.16+; 1.0.16 is only a crash fix in the official notes. Teach <strong>1.0.15</strong> as the feature version."},{"type":"prose","html":"{type:'gap'} Release notes do not name the exact buttons in the crop UI. Official fact: you select a video, crop its audio, and the file arrives through <strong>Imported</strong>. Use whatever crop/trim view your Note version opens. Do not invent a YouTube-in-Note downloader. Ableton Note.md’s “screen-record YouTube” idea is not in the official extracts — skip it."},{"type":"prose","html":"RN 2.0.1 fixed imported videos/audio (m4a, mp3) that were imported as mono. If a stereo video comes in mono on an older 2.0, update. Formats after crop follow the usual convert-to-WAV rule for compressed audio."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.0.15. If not, skip with a gap line.","From Note’s sample browser / Imported flow, select a short video from Photos or Files.","Crop the audio to the phrase you want. Confirm the import.","Open <strong>Libraries → User Library → Imported</strong> and load the result onto a pad or Sampler.","Play it. If it is unexpectedly mono on early 2.0, note the 2.0.1 fix.","Recite: video → crop audio → Imported folder; feature is 1.0.15, not 1.0.16."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which release added video-audio import? <strong>Answer:</strong> Note 1.0.15 (via the Imported folder).","Where does the cropped audio land? <strong>Answer:</strong> The <strong>Imported</strong> folder.","Does Note download YouTube internally? <strong>Answer:</strong> {type:'gap'} No official source describes an in-app YouTube grab."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.0.15 (Video-Audio Import); 1.0.16 (unrelated crash fix); 2.0.1 (stereo import fix)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Crop a 2–4 second phrase from a video you own and load it as a shot."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-5</code></em>"}]}],"minutes":8},{"id":"note-l9-3-6","title":"9.3.6 — External folders anywhere on device","blocks":[{"type":"step","title":"9.3.6 — External folders anywhere on device","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"On Note 1.7.2+, add a folder from anywhere on the iOS device to the Sample Browser so you can load those files without copying them into Imported first."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.7.2 External Folders: “Add external folders from anywhere on your iOS device in the Sample Browser.” That is the feature. You point Note at a folder that already exists (Downloads, a pack you keep in Files, a folder you share with another app) instead of duplicating every WAV into User Library → Imported."},{"type":"prose","html":"1.7.2 also adds the <strong>External</strong> top-level entry (9.3.7) and iCloud Drive download support (9.3.8). 2.0.1 later refreshes the browser when folder contents change (9.3.9) and includes external folders in search (9.3.10)."},{"type":"prose","html":"Below 1.7.2, {type:'gap'} this picker does not exist. Copy files into <strong>Imported</strong> instead."},{"type":"prose","html":"Format and 100 MB rules still apply. External is a location, not a new codec."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.7.2. If not, skip and use Imported.","Open <strong>Load Sample</strong> / the Sample Browser.","Add an external folder from somewhere on the device (Files locations the picker offers).","Open that folder and load one supported file onto a pad.","Play the pad.","Recite: 1.7.2 lets you add folders from anywhere on the device."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which version added external folders? <strong>Answer:</strong> Note 1.7.2.","Do you have to copy those files into Imported first? <strong>Answer:</strong> No. You add the folder in the Sample Browser.","What if you are on 1.7.1? <strong>Answer:</strong> Feature missing. Import into User Library → Imported instead."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.7.2 External Folders","Working with Samples in Note (Imported remains the copy-in path)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Add one pack folder you already keep on the device and load a single one-shot from it."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-6</code></em>"}]}],"minutes":8},{"id":"note-l9-3-7","title":"9.3.7 — External top-level browser entry","blocks":[{"type":"step","title":"9.3.7 — External top-level browser entry","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Open the <strong>External</strong> folder at the top level of the Sample Browser to reach folders you added in 9.3.6."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.7.2: “Added <strong>External</strong> folder at the top-level in Sample Browser to gain access to external folders.” After you add a folder from anywhere on the device, you do not hunt for it inside Core Library. You open <strong>External</strong>."},{"type":"prose","html":"In-app locations you already know:"},{"type":"list","items":["Libraries → Core Library","Libraries → User Library → Imported / Recordings","Libraries → Current Set → Recordings","<strong>External</strong> (1.7.2+) — the folders you attached"],"ordered":false},{"type":"prose","html":"{type:'gap'} Notes do not document remove/unfavorite of an external folder. If you cannot find an unlink control, leave the folder attached; it is a browser shortcut, not a second copy of every sample (unless you also imported)."},{"type":"prose","html":"2.0.1 fixed external folders that would not update immediately when files changed. If a new file is missing, leave and re-enter <strong>External</strong>, or rely on the 2.0.1 refresh (9.3.9)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.7.2 and that you added a folder in 9.3.6.","Open the Sample Browser from <strong>Load Sample</strong>.","Open the top-level <strong>External</strong> entry.","Enter your attached folder and load a file.","Compare with <strong>User Library → Imported</strong> so you feel the difference.","Recite: <strong>External</strong> is the top-level door to attached folders."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where does <strong>External</strong> sit? <strong>Answer:</strong> Top level of the Sample Browser (RN 1.7.2).","What does it contain? <strong>Answer:</strong> External folders you added from anywhere on the device.","Is <strong>External</strong> the same as Imported? <strong>Answer:</strong> No. Imported is copies inside User Library. External points at attached folders."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.7.2 (External top-level folder); 2.0.1 (external folder update fix)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Load one shot from <strong>External</strong> and one from <strong>Imported</strong> onto two pads. Label which pad is which in your notes."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-7</code></em>"}]}],"minutes":8},{"id":"note-l9-3-8","title":"9.3.8 — iCloud Drive downloads","blocks":[{"type":"step","title":"9.3.8 — iCloud Drive downloads","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Use 1.7.2 iCloud Drive download support so a cloud-only file actually arrives before you try to load it."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.7.2: External Folders include “support to download samples from iCloud Drive.” Files that show in iCloud Drive are not always on the device. Note can download them so the Sample Browser can use them."},{"type":"prose","html":"This is not Ableton Cloud (8 Sets, Note→Live transfer). Mixing the two names is a common error. Ableton Cloud holds Sets. iCloud Drive holds whatever files you stored in Apple’s drive. External folder support is how Note reaches those files."},{"type":"prose","html":"{type:'gap'} Notes do not describe a progress UI or a failure message for iCloud downloads. If a file will not play, wait for the download, check format/size, and retry. 2.0.1 browser refresh helps when the folder contents change after a download (9.3.9)."},{"type":"prose","html":"Cellular: Manual §1.1 lets you turn off Mobile/Cellular Data for Note so Cloud waits for Wi-Fi. That toggle is about Ableton Cloud transfers. A large iCloud sample still needs a network if it is not downloaded."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.7.2.","Put or locate a small WAV in iCloud Drive (Files app).","Add that iCloud folder as an External folder if it is not already attached.","In Note’s Sample Browser, open it and select the file so 1.7.2 can download it.","Load the file onto a pad once it is local.","Recite: iCloud Drive ≠ Ableton Cloud; 1.7.2 can download samples from iCloud Drive."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which version added iCloud Drive sample download support? <strong>Answer:</strong> 1.7.2.","Is that Ableton Cloud? <strong>Answer:</strong> No. Ableton Cloud syncs up to eight Note Sets.","What if the file is still cloud-only? <strong>Answer:</strong> Use the 1.7.2 download support, then load. A missing local file will not play."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.7.2 (iCloud Drive download support)","Ableton Note Manual §1.1 / FAQ (Ableton Cloud is a different service)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Download one iCloud one-shot and play it. If you do not use iCloud Drive, write a skip line and stay on local External/Imported."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-8</code></em>"}]}],"minutes":8},{"id":"note-l9-3-9","title":"9.3.9 — Browser refresh when folders change","blocks":[{"type":"step","title":"9.3.9 — Browser refresh when folders change","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"On Note 2.0.1+, expect the Sample Browser to update when directory contents change, including files added in other apps."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1 Improvements: “Browser now updates when directory contents change (e.g. adding loops in other apps).” The same release fixed “external folders would not update immediately when files changed.” Together: drop a loop into an attached folder or Imported (from Files, AirDrop, another app) and the browser should show it without a restart."},{"type":"prose","html":"Pre-2.0.1: RN 1.0.15 had to fix AirDrop imports that appeared only after re-entering the folder. If you are below 2.0.1, leave the folder and go back in. That is the sourced workaround."},{"type":"prose","html":"{type:'gap'} Notes do not document a manual Refresh button. If a file still hides, re-enter the folder, confirm the real path in Files, and check format/size."},{"type":"prose","html":"Search including external folders is the next lesson (also 2.0.1)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Read your version. Note whether you have the 2.0.1 refresh.","With Note in the background, add a small WAV to Imported or an External folder via Files.","Return to the Sample Browser and open that folder.","Confirm the new file appears (2.0.1+) or re-enter the folder (older).","Load the new file onto a pad.","Recite the version split: re-enter folder vs automatic update."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What did 2.0.1 change about the browser? <strong>Answer:</strong> It updates when directory contents change, e.g. loops added in other apps.","What older workaround exists? <strong>Answer:</strong> Leave the folder and re-enter (1.0.15 AirDrop fix culture).","Is there a documented Refresh button? <strong>Answer:</strong> {type:'gap'} No. Use re-enter or the 2.0.1 auto-update."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 (browser updates; external folder update fix); 1.0.15 (AirDrop visibility)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Add one file from Files while Note is open and prove whether your version shows it immediately."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-9</code></em>"}]}],"minutes":8},{"id":"note-l9-3-10","title":"9.3.10 — Search includes external folders","blocks":[{"type":"step","title":"9.3.10 — Search includes external folders","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"On Note 2.0.1+, use Sample Browser search and expect hits from attached External folders as well as the libraries."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.0.12 added search and favorite for samples and presets. RN 2.0.1: “Searching now includes external folders.” If you attached a pack in 9.3.6, you can type part of the filename instead of walking <strong>External</strong> by hand."},{"type":"prose","html":"Below 2.0.1, search exists (1.0.12) but {type:'gap'} official notes do not say it includes External (External itself is 1.7.2). On 1.7.2–2.0, browse <strong>External</strong> directly."},{"type":"prose","html":"Search does not bypass the 100 MB block or unsupported formats. A hit that will not load is still the format/size rule."},{"type":"prose","html":"Favorites (heart) remain useful for presets and samples you reuse (8.1.7 / 1.0.12). Search is for the long tail in External."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 2.0.1. If not, search Core/User Library only and browse <strong>External</strong> by hand.","Open <strong>Load Sample</strong>.","Type part of a filename you know lives in an External folder.","Select a hit and load it onto a pad.","Clear search and find the same file under <strong>External</strong> to confirm the path.","Recite: 2.0.1 search includes external folders."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["When did search start including External? <strong>Answer:</strong> Note 2.0.1.","When did sample search itself arrive? <strong>Answer:</strong> Note 1.0.12.","Does a search hit ignore the 100 MB limit? <strong>Answer:</strong> No. Samples larger than 100 MB cannot be imported or selected (RN 1.0.6)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.0.12 (search); 1.7.2 (External); 2.0.1 (search includes external folders)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Search for one External one-shot by a fragment of its name and load it without walking folders."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-10</code></em>"}]}],"minutes":8},{"id":"note-l9-3-11","title":"9.3.11 — 100 MB Cloud constraint","blocks":[{"type":"step","title":"9.3.11 — 100 MB Cloud constraint","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Treat 100 MB as both a Cloud warning threshold and a hard import/select limit, and keep sample data small enough to upload a Set."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.0.6:"},{"type":"list","items":["Warnings when a sample exceeds the <strong>100 MB</strong> size limit for Ableton Cloud","Samples larger than <strong>100 MB</strong> cannot be imported or selected in the browser"],"ordered":false},{"type":"prose","html":"FAQ: Cloud holds <strong>8 Sets</strong>. Cloud is transfer, not backup. A Set that is already local can still live in <strong>Files → … → Ableton Note → Projects</strong> even if Cloud refuses a giant sample. You cannot pick that giant file in the browser."},{"type":"prose","html":"Level 1 also phrases this as a warning at approximately 100 MB of sample data. per-sample 100 MB blocks import/select; Cloud warns at that Cloud limit."},{"type":"prose","html":"Crop (1.7.3) and shorter recordings keep you under the cap. Export Audio is unrelated (whole Set render). Splitting a 120 MB file outside Note is your job; Note will not import it."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Before import, check file size in the Files app.","If a file is over 100 MB, do not try to load it. Trim or split it elsewhere.","Import a file you know is small. Confirm it loads.","If Cloud is enabled, remember an over-limit sample also blocks a clean upload.","Prefer cropped takes (9.4.5) for long recordings.","Recite: &gt;100 MB cannot be imported or selected; Cloud warns at 100 MB."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What happens if a sample is larger than 100 MB? <strong>Answer:</strong> It cannot be imported or selected (RN 1.0.6).","What else did 1.0.6 add? <strong>Answer:</strong> Warnings when a sample exceeds the 100 MB Cloud limit.","Does Cloud become a backup if you stay under 100 MB? <strong>Answer:</strong> No. Cloud is still transfer, 8 Sets max."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.0.6","Note FAQ (8 Sets; Cloud is not backup)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Audit the samples you plan to import for 9.3.14. Reject anything near or over 100 MB."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-11</code></em>"}]}],"minutes":8},{"id":"note-l9-3-12","title":"9.3.12 — Uppercase WAV issues historically fixed","blocks":[{"type":"step","title":"9.3.12 — Uppercase WAV issues historically fixed","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Know that uppercase <code>.WAV</code> files failed to import on early Note and that RN 1.0.15 fixed it — so you do not “convert” a healthy file for the wrong reason."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.0.15 Fixes: “Audio Import: Fixed an issue where upper-case WAV files would not be imported.” If you are on 1.0.15 or later, <code>KICK.WAV</code> and <code>kick.wav</code> are both WAV. If a collaborator is on a pre-1.0.15 build, rename to lowercase <code>.wav</code> or have them update."},{"type":"prose","html":"Working with Samples still warns that some platforms display MP3s as WAV. A file named <code>.WAV</code> that is actually another type can still fail. The 1.0.15 fix is about the extension case, not about fake types."},{"type":"prose","html":"This is historical awareness, not a current workflow. Do not build a naming ritual around it unless you support old installs."},{"type":"prose","html":"Check <strong>Settings → Help</strong> before you blame the file."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Read your Note version.","If ≥ 1.0.15, import a file whose extension is <code>.WAV</code> (uppercase) if you have one.","Confirm it loads.","If &lt; 1.0.15 and it fails, rename to <code>.wav</code> or update Note.","If a “WAV” still fails, check the real type and size (9.3.1, 9.3.11).","Recite: uppercase WAV import was fixed in 1.0.15."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What was broken? <strong>Answer:</strong> Upper-case WAV files would not import.","Which version fixed it? <strong>Answer:</strong> Note 1.0.15.","Is every file named WAV actually WAV? <strong>Answer:</strong> No. Working with Samples: some platforms mislabel MP3 as WAV."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.0.15 (uppercase WAV import fix)","Working with Samples in Note (false WAV / unsupported type)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"If you have an old <code>.WAV</code> from Windows, import it once on your current version and file this as solved."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-12</code></em>"}]}],"minutes":8},{"id":"note-l9-3-13","title":"9.3.13 — iPad multi-sample drag to pads","blocks":[{"type":"step","title":"9.3.13 — iPad multi-sample drag to pads","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"On iPad Note 1.5.2+, drag samples onto Sample View; drag several at once onto a Drum Rack to fill pads from the selected pad onward."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.5.2 (iPad): “Samples can now be dragged and dropped onto the sample view in Drum Kits and Melodic samplers. In drum kits, dragging multiple samples will load them onto multiple pads, starting from the currently selected one.”"},{"type":"prose","html":"Gates: <strong>iPad</strong> and <strong>1.5.2+</strong>. On iPhone, {type:'gap'} this drag behavior is not documented. Use <strong>Load Sample</strong> per pad. On iPad below 1.5.2, same fallback."},{"type":"prose","html":"Select the starting pad first. The first file in the drag goes there; the rest fill following pads. You still have 16 Drum pads. Files must be supported and under 100 MB."},{"type":"prose","html":"This is faster than AirDrop-per-file for a kit you already have in Files or External. It does not slice a break (9.4.9). It loads whole files."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm you are on iPad and version ≥ 1.5.2. If not, skip to per-pad <strong>Load Sample</strong>.","Open a Drum Rack. Select the first empty pad you want to fill.","From Files or a split view, drag one sample onto Sample View. Confirm it loads.","Drag three samples together onto the kit. Confirm they occupy consecutive pads from the selection.","Play those pads.","Recite: iPad 1.5.2+ multi-drag fills pads starting at the selected one."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which device and version get this drag? <strong>Answer:</strong> iPad, Note 1.5.2+.","Where do multiple files land on a Drum Rack? <strong>Answer:</strong> On multiple pads, starting from the currently selected pad.","Does this work the same on iPhone? <strong>Answer:</strong> {type:'gap'} Not documented. Use Load Sample."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.5.2 (iPad drag and drop; multi-sample to pads)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"If you are on iPad 1.5.2+, drop three one-shots for 9.3.14 in one drag. If not, load them one at a time."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-13</code></em>"}]}],"minutes":8},{"id":"note-l9-3-14","title":"9.3.14 — import 3 files; place on kit","blocks":[{"type":"step","title":"9.3.14 — import 3 files; place on kit","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.3 — Import pipelines</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Import three one-shots through any legal path and place them on a Drum Rack as a playable mini-kit."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"This lab uses only facts from 9.3.1–9.3.13. Pick three files: WAV/AIFF/M4A/MP3, each under 100 MB. Bring them in via AirDrop, Share, Files → Imported, External (1.7.2+), iPad drag (1.5.2+), or video crop (1.0.15+). Load onto three pads with <strong>Load Sample</strong>, or one multi-drag on iPad."},{"type":"prose","html":"Assign roles the beatmaking extract understands: a low hit, a snappy hit, a tick. You may keep one environmental pad from 9.2.5 so the kit is half recorded, half imported."},{"type":"prose","html":"Do not slice yet (9.4.9). Do not use a 2.x audio track as the destination. Sampler C3 is for pitched files; this lab is a kit."},{"type":"prose","html":"If a file fails: format, uppercase-WAV on ancient builds, 100 MB, or a folder that has not refreshed."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Choose three legal files and a destination empty Drum Rack.","Import them through the path your device supports fastest.","Place them on three pads. Check start and gain (+24 to −70 dB).","Capture a two-bar pattern.","Solo the kit. If one file is wrong, <strong>Swap Sample</strong> (manual §9.2).","Play the kit from memory and name each pad’s source (AirDrop, Files, External, record)."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What formats are legal? <strong>Answer:</strong> WAV, AIFF, M4A, MP3 (M4A/MP3 convert to WAV).","Where do you load a file onto an empty pad? <strong>Answer:</strong> Select the pad → <strong>Load Sample</strong> (or iPad 1.5.2+ drag).","What is the hard size stop? <strong>Answer:</strong> Samples larger than 100 MB cannot be imported or selected."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual ch.9; §9.2 Swap Sample","Working with Samples in Note","Note FAQ; RN 1.0.6 / 1.5.2 / 1.7.2 as used"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Keep this three-pad kit. Module 9.4 will edit, reverse, and maybe slice — not replace the import skill."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-3-14</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-9-4-104","code":"9.4","title":"9.4","blurb":"9.4","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l9-4-1","title":"9.4.1 — Sample tab waveform","blocks":[{"type":"step","title":"9.4.1 — Sample tab waveform","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Open the Sample tab, read the waveform, and use the documented drag and pinch gestures before you touch start/end markers."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §7.3: on Drum Rack or Melodic Sampler presets, the second tab holds the sample loaded on that track (or the selected pad). Core Library presets already have a sample; you can change it or load your own."},{"type":"prose","html":"Manual ch.9 gestures on that waveform:"},{"type":"list","items":["Drag left or right to set a different starting point","Two-finger pinch to zoom while you adjust the start","Drag up or down to set gain from <strong>+24</strong> to <strong>−70 dB</strong>"],"ordered":false},{"type":"prose","html":"RN 1.0.6: the waveform tab is selected by default when it is empty. RN 1.0.6 also enabled direct-touch on Pads and Waveform views (accessibility). RN 1.7.2 later adds dedicated start/stop markers (9.4.2). This lesson is the pre-marker surface plus the tab itself."},{"type":"prose","html":"Recorded takes auto-crop to the first transient. If the waveform looks empty, you are on the wrong pad or you have not loaded/recorded yet."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open a Drum pad or Melodic Sampler that has a sample.","Tap the Sample tab (second tab).","Pinch to zoom in on the attack. Pinch out.","Drag the waveform left/right and play the pad. Return to a sensible start.","Drag up/down to hear gain. Stay out of obvious clipping.","Recite the three gestures: start, pinch zoom, gain."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which tab shows the sample? <strong>Answer:</strong> The second tab on Drum Rack or Melodic Sampler (Manual §7.3).","How do you change gain on the waveform? <strong>Answer:</strong> Drag up or down, range +24 to −70 dB.","How do you zoom? <strong>Answer:</strong> Two-finger pinch."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §7.3 Sample Tab; ch.9 waveform gestures","Note Release Notes 1.0.6 (empty waveform tab; direct-touch)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"On one imported pad and one recorded pad, set start and gain by ear. Do not crop yet."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-1</code></em>"}]}],"minutes":8},{"id":"note-l9-4-2","title":"9.4.2 — Start/end markers","blocks":[{"type":"step","title":"9.4.2 — Start/end markers","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"On Note 1.7.2+, trim a sample with the dedicated start and end markers instead of only dragging the waveform."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.7.2: “Samplers: New start/stop editing workflow with dedicated markers.” That is the version gate. The local manual only documents dragging the waveform to change the <strong>start</strong>. End markers are release-note. Below 1.7.2, drag start only and treat end-trim as a gap."},{"type":"prose","html":"1.7.3: when start/end change, Sample Options can <strong>crop and save</strong> (9.4.5). Until you crop, you are previewing a region of the same file. 1.7.3 also fixed: tapping a new pad while holding a marker changed the wrong pad; zoomed-in left handle nudged the right marker. If a handle misbehaves on 1.7.2, know the 1.7.3 fix."},{"type":"prose","html":"Slicing (same 1.7.2) lets you change start/end on initial slice and adjust per-slice starts (9.4.9). This lesson is one pad, one sample."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.7.2. If not, use waveform-drag start only.","Open Sample View on a long take or imported loop.","Drag the start marker to the first useful transient.","Drag the end marker to cut the tail you do not want.","Play the pad. Re-adjust both markers.","Recite: 1.7.2 dedicated start/stop markers; manual-only builds have start-drag only."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which version added dedicated start/stop markers? <strong>Answer:</strong> Note 1.7.2.","What does the local manual document instead? <strong>Answer:</strong> Drag the waveform left/right to set the starting point.","Does moving markers immediately rewrite the file? <strong>Answer:</strong> Not until you crop and save (1.7.3 Sample Options)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.7.2 (dedicated markers); 1.7.3 (crop/save; marker fixes)","Ableton Note Manual ch.9 (start via waveform drag)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Trim one cymbal or room take so only the useful body remains between the markers."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-2</code></em>"}]}],"minutes":8},{"id":"note-l9-4-3","title":"9.4.3 — Double-tap zoom to selection","blocks":[{"type":"step","title":"9.4.3 — Double-tap zoom to selection","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Double-tap the sampler waveform (1.7.2+) to zoom to the selected start/end range, then zoom back out to edit."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.7.2: “Samplers: Double tap to zoom to selected range.” Combined with dedicated markers, this is how you place an end point on a long file without pinching blindly. The manual’s pinch zoom still works. Double-tap is the selection zoom."},{"type":"prose","html":"{type:'gap'} Notes do not say whether a second double-tap zooms out. If it does not, pinch out, or use whatever zoom-out your build offers. 1.7.3 improved waveform rendering when zoomed to sample level and fixed a zoomed-in left-handle bug."},{"type":"prose","html":"Do not confuse this with MIDI Editor loop-brace zoom (swipe up on the brace). That is notes, not samples."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.7.2.","Set start and end markers around a short region.","Double-tap the waveform. Confirm you are zoomed to that range.","Nudge a marker at the zoomed view.","Pinch (or double-tap again if it toggles) to see the whole file.","Repeat from memory on a second pad."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What does a double-tap do on the sampler waveform in 1.7.2+? <strong>Answer:</strong> Zooms to the selected range.","What older zoom still exists? <strong>Answer:</strong> Two-finger pinch (manual ch.9).","Is this the MIDI Editor zoom? <strong>Answer:</strong> No. MIDI zoom is pinch / loop-brace swipe."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.7.2 (double tap to selected range); 1.7.3 (zoom rendering)","Ableton Note Manual ch.9 (pinch zoom)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Zoom to the attack of a kick, set start on the transient, zoom out, and play the pad."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-3</code></em>"}]}],"minutes":8},{"id":"note-l9-4-4","title":"9.4.4 — Scroll acceleration","blocks":[{"type":"step","title":"9.4.4 — Scroll acceleration","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"On Note 1.7.2+, scroll a long waveform using the documented scroll acceleration instead of only pinching."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.7.2: “Samplers: Scrolling now uses scroll acceleration.” That is the entire official sentence. Fast flicks travel farther along a long take; slow drags stay precise. Use it after you zoom (pinch or double-tap) when the file is a phrase, not a one-shot."},{"type":"prose","html":"{type:'gap'} Notes do not give a numeric acceleration curve or a setting to disable it. If a flick overshoots, move slower or zoom in first."},{"type":"prose","html":"1.7.3 improved rendering when zoomed to sample level — acceleration plus that fix is what makes long recordings editable. Below 1.7.2, rely on pinch and waveform drag only."},{"type":"prose","html":"Do not confuse waveform scrolling with Session View track-header scrolling (a 1.2 fix). This lesson is Sample View."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.7.2.","Load or record a long sample (several seconds).","Zoom in. Flick-scroll along the waveform, then scroll slowly.","Stop on a transient and set the start marker.","Flick to the tail and set the end marker.","Recite: 1.7.2 sampler scrolling uses acceleration."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which version added scroll acceleration on samplers? <strong>Answer:</strong> 1.7.2.","Why use it? <strong>Answer:</strong> To move through a long waveform faster than a constant-speed drag, then slow down for a transient.","Is there a documented off switch? <strong>Answer:</strong> {type:'gap'} No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.7.2 (scroll acceleration); 1.7.3 (zoomed waveform rendering)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"On one long take, find the start and end only by scrolling and markers — no guesswork at full zoom-out."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-4</code></em>"}]}],"minutes":8},{"id":"note-l9-4-5","title":"9.4.5 — Crop and save when start/end change","blocks":[{"type":"step","title":"9.4.5 — Crop and save when start/end change","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"After you move start/end, crop and save from Sample Options (1.7.3) so the file on disk matches the region you play."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.7.3: “Sample Options: When the start/end of a sample changes, you can now crop and save the sample.” Markers alone (1.7.2) preview a region. Crop writes that region. Saving matters if you want the trimmed file in <strong>User Library → Recordings</strong> or to keep Cloud/sample size down (9.3.11)."},{"type":"prose","html":"Manual §9.2: <strong>Save Sample</strong> appears for samples recorded into the device and writes to Recordings → Drum Sampler or Melodic Sampler. RN 1.0.12 moved sample saving from Sample Options into the Browser, then 1.5.2 put Sample Options on <strong>…</strong>, and 1.7.3 added crop-and-save when start/end change. Use <strong>…</strong> on 1.5.2+ to find the crop/save action."},{"type":"prose","html":"{type:'gap'} Exact button wording beyond “crop and save” is not published. Use the Sample Options command your build shows after markers move."},{"type":"prose","html":"Cropping a huge take is the honest way to stay under 100 MB."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.7.3. If you only have 1.7.2, set markers and skip crop.","Change start and end on a recorded or imported sample.","Open Sample Options (<strong>…</strong>).","Crop and save. Name the file if asked.","Reload the saved file from Recordings or Imported and confirm the tail is gone.","Recite: 1.7.3 crop-and-save after start/end change."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which version added crop and save when start/end change? <strong>Answer:</strong> 1.7.3.","Why crop instead of only moving markers? <strong>Answer:</strong> Crop saves the region as the sample, which also helps the 100 MB Cloud/import limit.","Where do recorded saves go? <strong>Answer:</strong> User Library → Recordings → Drum Sampler or Melodic Sampler."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.7.3; 1.5.2 (… menu); 1.0.12 (save moved to browser)","Ableton Note Manual §9.2 Save Sample","Working with Samples in Note (save for use in other Sets)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Crop one long environmental take down to the hit. Keep the cropped file on the pad."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-5</code></em>"}]}],"minutes":8},{"id":"note-l9-4-6","title":"9.4.6 — Reverse (naming scheme RN)","blocks":[{"type":"step","title":"9.4.6 — Reverse (naming scheme RN)","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Reverse a sample and recognize the 1.4.3 naming change from <code>_rev.wav</code> to <code>' R'.wav</code>."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.0.12 added <strong>Reverse Sample</strong>. That is the feature. Beatmaking extract already treats a reverse cymbal as a useful shot — you will build one in 9.4.13."},{"type":"prose","html":"RN 1.4.3 tweak: “Naming scheme for reversed samples has been changed from <code>_rev.wav</code> to <code>' R'.wav</code>.” If you browse User Library and see <code>crash_rev.wav</code>, that is the old scheme. Newer reverses look like <code>crash R.wav</code> (the notes write <code>' R'.wav</code>). Do not treat those as two different files you must keep."},{"type":"prose","html":"RN 1.7.3 fixed flickering when reversing a sample. If reverse flashes on 1.7.2, that fix is why you update."},{"type":"prose","html":"{type:'gap'} Official notes do not say whether reverse is destructive or a copy. After you reverse, check the filename and, if you need the forward version, <strong>Swap</strong> back to the original from Imported/Recordings."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.0.12.","Select a cymbal, vocal, or noise pad.","Reverse it from Sample Options / the reverse control your version shows.","Read the new name: <code>_rev</code> (old) vs <code> R</code> (1.4.3+).","Play the pad. Reverse again if you need the forward file back, or swap to the original.","Recite the two naming schemes and the 1.4.3 change."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["When did Reverse arrive? <strong>Answer:</strong> Note 1.0.12.","What did 1.4.3 change? <strong>Answer:</strong> Reversed names went from <code>_rev.wav</code> to <code>' R'.wav</code>.","What did 1.7.3 fix? <strong>Answer:</strong> Flickering when reversing a sample."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.0.12 (Reverse Sample); 1.4.3 (naming scheme); 1.7.3 (flicker fix)","Beatmaking with Ableton Note (reverse cymbal shot)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Reverse one metallic or cymbal sample and leave it for 9.4.13. Keep the forward file available via Swap or a second pad."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-6</code></em>"}]}],"minutes":8},{"id":"note-l9-4-7","title":"9.4.7 — Sample Options menu “…”","blocks":[{"type":"step","title":"9.4.7 — Sample Options menu “…”","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Open Sample Options from the waveform (manual) and from <strong>…</strong> (1.5.2+), and list the commands the manual actually names."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §9.2: tap the sample’s waveform to open Sample Options. Commands differ slightly by device."},{"type":"prose","html":"<strong>Drum Rack:</strong>"},{"type":"list","items":["<strong>Choke Sample</strong> — this sample stops when other samples in the same Choke group play. <strong>One Choke group per Drum Rack.</strong>","<strong>Mode</strong> — <strong>Trigger</strong> plays through; <strong>Gate</strong> stops on release.","<strong>Save Sample</strong> — if recorded, saves to Recordings → Drum Sampler","<strong>Swap Sample</strong> — replace the pad’s sample"],"ordered":false},{"type":"prose","html":"<strong>Melodic Sampler:</strong> Mode, Save Sample (to Melodic Sampler folder if recorded), Swap Sample. No Choke."},{"type":"prose","html":"RN 1.5.2: Sample Options is also available via <strong>…</strong> on each sample, and gained the Resampling/Recording toggle. RN 1.0.15 redesigned Sample Options. RN 1.0.12 added Reverse and moved save toward the Browser. RN 1.7.3 added crop-and-save. Your menu is the union of those versions."},{"type":"prose","html":"Do not invent Live Simpler commands that are not in this list."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Select a Drum pad with a sample. Tap the waveform. Also tap <strong>…</strong> if you have 1.5.2+.","Read <strong>Choke</strong>, <strong>Mode</strong>, <strong>Save</strong>, <strong>Swap</strong>, and any reverse/crop/resample items your version adds.","Set <strong>Mode</strong> to Trigger, play a short tap. Set Gate, play a held tap.","Open Melodic Sampler Options and confirm Choke is absent.","Swap a sample, then swap back.","Recite Drum vs Sampler option lists from memory."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How does the manual open Sample Options? <strong>Answer:</strong> Tap the sample’s waveform.","What extra opener did 1.5.2 add? <strong>Answer:</strong> <strong>…</strong> on each sample.","How many Choke groups exist per Drum Rack? <strong>Answer:</strong> One."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §9.2 Sample Options","Note Release Notes 1.0.12 / 1.0.15 / 1.5.2 / 1.7.3 (menu evolution)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Set snare to Trigger and a long texture pad to Gate. Play both. Leave Choke off until 9.4.10."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-7</code></em>"}]}],"minutes":8},{"id":"note-l9-4-8","title":"9.4.8 — Gain accuracy fixes awareness","blocks":[{"type":"step","title":"9.4.8 — Gain accuracy fixes awareness","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Use waveform gain with the official +24 to −70 dB range, and know that 1.7.3 fixed inaccurate Sample Gain display."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual ch.9: drag up or down on the sample waveform to set gain anywhere between <strong>+24</strong> and <strong>−70 dB</strong>. That is the control and the range. RN 2.0.1 audio clips also have gain dials and swipe-up/down on the waveform (9.5.9) — different path. This lesson is Sampler / Drum Rack Sample View."},{"type":"prose","html":"RN 1.7.3 Fixes: “Sample Gain was shown inaccurately.” If you are on 1.7.2 or earlier, the number you see may not match the sound. Trust your ear, then update. On 1.7.3+ treat the displayed gain as corrected."},{"type":"prose","html":"Double-tap reset (RN 1.0.15) applies to parameters and the mixer fader. {type:'gap'} Notes do not say double-tap resets waveform gain. If it does on your build, record it; do not require it."},{"type":"prose","html":"Gain is not Saturator and not the mixer slider. It is the sample’s own level before pad FX and the rack."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open a pad that is too quiet or too hot.","Drag the waveform up/down. Watch the gain read-out if your version shows one.","Compare the read-out to what you hear. If they disagree and you are &lt; 1.7.3, write that as the 1.7.3 bug.","Set a level that sits with the rest of the kit.","Check the mixer slider so you are not compensating twice.","Recite the range: +24 to −70 dB; display fixed in 1.7.3."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is the official waveform gain range? <strong>Answer:</strong> +24 to −70 dB.","What did 1.7.3 fix? <strong>Answer:</strong> Sample Gain was shown inaccurately.","Is this the 2.x audio-clip gain dial? <strong>Answer:</strong> No. That is RN 2.0.1 on audio tracks."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual ch.9 (gain drag and range)","Note Release Notes 1.7.3 (gain display); 1.0.15 (double-tap on parameters/faders)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Match one imported pad to one recorded pad by ear using only waveform gain."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-8</code></em>"}]}],"minutes":8},{"id":"note-l9-4-9","title":"9.4.9 — Slice to pads (1.7.2+): initial start/end; per-slice markers","blocks":[{"type":"step","title":"9.4.9 — Slice to pads (1.7.2+): initial start/end; per-slice markers","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Slice a sample onto individual Drum Sampler pads, set start/end at the first slice, then adjust per-slice start markers."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.7.2 Sample Slicing:"},{"type":"list","items":["Slice samples to individual pads in Drum Sampler","Adjust individual start markers for a sample in slicing mode","Change Start/End on initial slicing"],"ordered":false},{"type":"prose","html":"That is the whole official UI description. {type:'gap'} The notes do not name a <strong>Slice</strong> button, slice count, or transient sensitivity. Use the slicing mode your 1.7.2+ Drum Sampler actually shows. Below 1.7.2, this lesson is a skip."},{"type":"prose","html":"Destination is <strong>Drum Sampler pads</strong>, not Melodic Sampler. You still have 16 pads. 9.4.12 will aim for eight pads. Choke on those pads is 9.4.10 (2.0.1 now sets choke on sliced pads)."},{"type":"prose","html":"Manual copy/paste of pads (RN 1.0.12 / §7.2 culture) is a slower pre-slice chop method. Prefer official slice when you have 1.7.2+."},{"type":"prose","html":"Sliced pads are still the sampler path: transpose couples speed; no warp (FAQ). A 2.x audio track is not a slicer."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.7.2. If not, skip.","Load a break or phrase onto a Drum pad.","Enter slicing mode. Set initial start/end so you are not slicing silence.","Slice onto multiple pads.","In slicing mode, adjust an individual start marker on one slice. Play that pad.","Recite: 1.7.2 slice to Drum pads; initial start/end; per-slice starts."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which instrument receives slices? <strong>Answer:</strong> Drum Sampler pads (RN 1.7.2).","What can you set on the first slice action? <strong>Answer:</strong> Start/End on initial slicing.","Can you move starts after slicing? <strong>Answer:</strong> Yes. Individual start markers in slicing mode."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.7.2 Sample Slicing","Note FAQ (no warp on sampler path)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Slice one short phrase onto at least four pads and play them as a new rhythm. Refine in 9.4.12."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-9</code></em>"}]}],"minutes":8},{"id":"note-l9-4-10","title":"9.4.10 — Choke group on sliced pads","blocks":[{"type":"step","title":"9.4.10 — Choke group on sliced pads","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Use the single Drum Rack Choke group so overlapping slices cut each other off, and know 2.0.1 now sets choke on sliced pads."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §9.2: <strong>Choke Sample</strong> means the sample stops when other samples in the same Choke group play. “There is only one Choke group per Drum Rack.” Enable Choke on the pads that should interrupt each other — typical for chopped breaks."},{"type":"prose","html":"RN 2.0.1 Fixes: “Choke group is now set on sliced pads.” Before that fix, a 1.7.2 slice session might leave choke off. On 2.0.1+, new slices should arrive already choked. Still verify <strong>Choke Sample</strong> in Sample Options. On 1.7.2–2.0, turn it on yourself after slicing."},{"type":"prose","html":"Choke is not Gate/Trigger. Gate stops on pad release. Choke stops when another choked pad fires. You can use both."},{"type":"prose","html":"Melodic Sampler has no Choke in the manual’s option list."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open a sliced Drum Rack (or slice now).","On two adjacent slices, open Sample Options and check <strong>Choke Sample</strong>.","If you are &lt; 2.0.1 and choke is off, enable it on the slice pads you will play together.","Play overlapping slices quickly. Confirm the previous slice cuts.","Disable choke on one perc pad that should ring.","Recite: one choke group per rack; 2.0.1 sets choke on sliced pads."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How many Choke groups does a Drum Rack have? <strong>Answer:</strong> One.","What did 2.0.1 change? <strong>Answer:</strong> Choke group is now set on sliced pads.","Does Choke exist on Melodic Sampler? <strong>Answer:</strong> Not in the manual’s Sampler options list."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §9.2 Choke Sample","Note Release Notes 2.0.1 (choke set on sliced pads)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Play the sliced break with choke on. Then play it with choke off. Keep the tighter one."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-10</code></em>"}]}],"minutes":8},{"id":"note-l9-4-11","title":"9.4.11 — Missing sample warnings after delete","blocks":[{"type":"step","title":"9.4.11 — Missing sample warnings after delete","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Recognize the in-Set message/views Note shows when a sample has been deleted, and recover by swapping a replacement."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 1.0.12 Tweaks: “Samples: Added message/views in sets for samples that have been deleted.” If you delete a user sample or folder in the browser (that release also allowed deleting user samples, presets, and folders), open Sets that still reference the file will warn instead of failing silently."},{"type":"prose","html":"{type:'gap'} The exact warning copy is not published. Treat any missing-sample message/view as this 1.0.12 feature. Do not delete User Library contents to “test” unless you have a Files backup (Level 1: back up the Ableton Note folder)."},{"type":"prose","html":"Recovery that is sourced: <strong>Swap Sample</strong> (manual §9.2) to load another file from Imported, Recordings, Core Library, Current Set, or External (1.7.2+). Re-import if you still have the original outside Note. Cloud is not a backup of deleted user samples."},{"type":"prose","html":"RN 1.0.15 mentioned improved stability with incorrectly formatted sample references — a related class of broken links, not a second UI."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Know where your user samples live (Files → Ableton Note → User Library).","Do <strong>not</strong> mass-delete. If you already see a missing-sample view, read it.","On the affected pad, open Sample Options and <strong>Swap Sample</strong>.","Load a replacement from Imported, Recordings, or Core Library.","Play the pad. Confirm the warning is gone.","Recite: 1.0.12 shows message/views for deleted samples; swap or re-import."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which version added missing-sample views? <strong>Answer:</strong> 1.0.12.","How do you put a new file on that pad? <strong>Answer:</strong> <strong>Swap Sample</strong> (or Load on an empty pad).","Will Cloud restore a deleted user sample automatically? <strong>Answer:</strong> No. Cloud transfers Sets; it is not a backup system."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.0.12 (deleted-sample message/views; delete user samples)","Ableton Note Manual §9.2 Swap Sample","Note FAQ (Cloud is not backup)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"If any pad in your Set already shows a missing sample, swap it now. Otherwise write where you would look first: User Library in Files."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-11</code></em>"}]}],"minutes":8},{"id":"note-l9-4-12","title":"9.4.12 — slice a break to 8 pads","blocks":[{"type":"step","title":"9.4.12 — slice a break to 8 pads","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Slice one break or phrase onto eight Drum pads, fix starts, enable choke, and play a new pattern."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"This lab only combines 9.4.9–9.4.10. RN 1.7.2 slices to Drum Sampler pads; you can set start/end on the initial slice and then move per-slice starts. A Drum Rack has 16 pads; eight leaves room for the 9.3.14 one-shots. 2.0.1 sets choke on sliced pads; otherwise turn <strong>Choke Sample</strong> on. One choke group per rack."},{"type":"prose","html":"{type:'gap'} Sources do not guarantee an “8 slices” preset. Choose eight regions by ear, or slice more and mute extras. If you lack 1.7.2, skip with a gap line — do not invent a fake slicer."},{"type":"prose","html":"FAQ: these pads are not warped. If the break was at another tempo, it will not magically lock to the Set (that is 2.x audio tracks). Play the slices as hits."},{"type":"prose","html":"Limitation (Beatmaking): eight pads, one break, no extra FX until the pattern works."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 1.7.2. Load a break onto a Drum pad.","Set initial start/end around the useful phrase.","Slice so you can play eight hits (use eight pads; ignore extras).","Adjust per-slice starts on any late pad.","Confirm choke (on by default in 2.0.1; enable earlier).","Capture a two-bar pattern that is not the original order."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How many pads does a Drum Rack have? <strong>Answer:</strong> 16. This lab uses 8 of them.","Why enable choke? <strong>Answer:</strong> So overlapping slices cut, one group per rack.","Will the break warp to the Set tempo on this path? <strong>Answer:</strong> No. Sampler/Drum Rack path has no warp (FAQ)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.7.2 slicing; 2.0.1 choke on slices","Ableton Note Manual §9.2 Choke; Drum Rack 16 pads","Note FAQ (no warp)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Keep the eight-pad instrument. Play it once tomorrow before you add Reverb. Memorable pattern stays."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-12</code></em>"}]}],"minutes":8},{"id":"note-l9-4-13","title":"9.4.13 — reverse cymbal transition shot","blocks":[{"type":"step","title":"9.4.13 — reverse cymbal transition shot","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.4 — Sample edit tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Build a reverse cymbal (or metallic) shot and place it as a transition into the next scene."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Beatmaking extract: shots stop a loop from going “bo-ring” — “a vocal phrase, a reverse cymbal, or a piano note with a long reverb.” RN 1.0.12 gives you Reverse. Trim with 1.7.2 markers so the swell ends on a downbeat. Crop/save (1.7.3) if you want a small file. Name will follow <code>_rev</code> or <code> R</code> (1.4.3)."},{"type":"prose","html":"Put the shot on its own pad. <strong>Mode = Trigger</strong> so a short tap plays the whole swell. Do not choke it against the hats if you want the swell to finish — choke would cut it when the next hat fires. Optionally <strong>Pad FX</strong> Reverb with <strong>Send Amount</strong> up on this pad only (Level 8)."},{"type":"prose","html":"Launch it in the bar before a scene change (8.4.12–8.4.13 culture). Clip max 16 bars; one-bar or two-bar clip is enough."},{"type":"prose","html":"This is still the sampler path. If you need the cymbal to follow tempo independently of pitch, that is a 2.x audio clip (9.5), not this pad."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Load a cymbal, crash, or bright noise. Reverse it (9.4.6).","Set start/end so the swell ends cleanly. Crop/save if you have 1.7.3.","Set <strong>Mode</strong> to <strong>Trigger</strong>. Leave choke off on this pad.","Capture a 1- or 2-bar clip that only plays this pad near the end.","Put that clip in the scene before your next section. Launch the scenes.","Recite: reverse + trigger + own pad + scene handoff."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which source recommends a reverse cymbal shot? <strong>Answer:</strong> Beatmaking with Ableton Note.","Why Trigger, not Gate? <strong>Answer:</strong> Trigger plays the sample all the way through after a tap (manual §9.2).","Should this pad share choke with hats? <strong>Answer:</strong> Usually no — choke would cut the swell."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Beatmaking with Ableton Note (reverse cymbal shot)","Ableton Note Manual §9.2 Mode / Choke","Note Release Notes 1.0.12 Reverse; 1.4.3 naming; 1.7.2–1.7.3 edit/crop"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Leave the reverse shot in the Set. You now have recorded hits, imports, slices, and a transition sample."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-4-13</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-9-5-105","code":"9.5","title":"9.5","blurb":"9.5","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l9-5-1","title":"9.5.1 — Version check ≥ 2.0 else skip + gap","blocks":[{"type":"step","title":"9.5.1 — Version check ≥ 2.0 else skip + gap","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Read <strong>Settings → Help</strong>, and either enter Module 9.5 or write a skip-gap and stay on the Sampler/Drum Rack path."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"The local <em>Ableton Note Manual</em> has no audio-track chapter. Audio tracks are RN <strong>2.0.1</strong>: record loops in session or track view; loops are warped; Beat/Synth/<strong>Audio</strong> add-track buttons. FAQ still says “Warping is not currently available” and that Transpose on Sampler/Drum Rack changes speed. Treat both as dated. Sampler path = FAQ. Audio tracks 2.0+ = RN."},{"type":"prose","html":"If your version is below 2.0 / 2.0.1:"},{"type":"prose","html":"<code>{type:'gap'} Note &lt;version&gt; lacks audio tracks (needs RN 2.0.1). Module 9.5 skipped. Sampler/Drum Rack path only; warp not available there.</code>"},{"type":"prose","html":"Do not fake audio tracks with resample. Resample still lands in a sampler (9.2). Do not install AUv3."},{"type":"prose","html":"If you are on 2.0.1+, write the version and continue. 9.5.5 will lock the two warp rules so you never blend them."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open <strong>Settings → Help</strong>. Write the version.","If &lt; 2.0.1, write the gap line and stop this module.","If ≥ 2.0.1, look at the add-track controls for an <strong>Audio</strong> button (9.5.2).","Confirm you still also have Drum Rack and Sampler — they did not go away.","Write two labels in your notes: “sampler = no warp” and “audio track = warped loops.”","Recite the skip rule from memory."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where is the version number? <strong>Answer:</strong> <strong>Settings → Help</strong>.","What do you do below 2.0.1? <strong>Answer:</strong> Write a <code>{type:'gap'}</code> line and skip 9.5.","Does resample replace audio tracks? <strong>Answer:</strong> No. Resample writes into Drum Rack or Sampler."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (Settings → Help; warping not available — sampler context)","Note Release Notes 2.0.1 Audio Tracks"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Circle this module in your session plan as <strong>run</strong> or <strong>skip</strong>. If skip, your Level 9 product is the 9.2–9.4 sampler work."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-1</code></em>"}]}],"minutes":8},{"id":"note-l9-5-2","title":"9.5.2 — Add Audio track","blocks":[{"type":"step","title":"9.5.2 — Add Audio track","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Add an <strong>Audio</strong> track with the 2.0.1 add-track buttons and keep it distinct from Beat and Synth tracks."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1: “New add-track buttons: Beat, Synth, and <strong>Audio</strong> track.” You still have the 8-track Set limit (FAQ). Adding Audio does not raise that cap. Pre-2.x you added tracks by swiping (manual) and chose a Track Preset. 2.0.1 makes the three jobs explicit: drums, synth, audio."},{"type":"prose","html":"An Audio track is where warped loops live (9.5.4). It is not a Drum Rack pad and not Melodic Sampler. Empty audio-clip view shares features with the updated empty sampler view (same RN). Monitoring and the microphone button live there (9.1.4–9.1.5)."},{"type":"prose","html":"{type:'gap'} Exact icon art and whether swipe-left still exists beside the new buttons are not described. Use the <strong>Audio</strong> add-track control you see. If you cannot add a ninth track, you hit the 8-track limit — delete or reuse a track."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm version ≥ 2.0.1 (else skip the module).","Count existing tracks. Stay at 8 or fewer.","Use the add-track control and choose <strong>Audio</strong>.","Confirm you did not add Beat or Synth by mistake.","Open the empty audio view. Note the microphone / + affordances for 9.5.3 and 9.5.6.","Recite: Beat, Synth, Audio; 8 tracks max."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What three add-track buttons did 2.0.1 add? <strong>Answer:</strong> Beat, Synth, and Audio.","How many tracks can a Set hold? <strong>Answer:</strong> 8.","Is an Audio track a Sampler? <strong>Answer:</strong> No. Sampler is still the instrument path. Audio is the 2.x loop path."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 (add-track buttons; empty audio view)","Note FAQ (max 8 tracks)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Add one Audio track to the Set that already has your Drum Rack. Do not record yet."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-2</code></em>"}]}],"minutes":8},{"id":"note-l9-5-3","title":"9.5.3 — Record audio loops Session or track view","blocks":[{"type":"step","title":"9.5.3 — Record audio loops Session or track view","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Record an audio loop from Session View or from the audio track view on Note 2.0.1+."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1 first bullet: “Record audio loops in session or track view.” Two official places, one job. Session View is the clip grid. Track view is the audio track / empty clip surface (microphone button, later + menu). You can monitor and process through the audio track (same RN). Inputs: built-in mics or external devices (9.1.5)."},{"type":"prose","html":"This recording creates an <strong>audio clip</strong>, not a Drum pad sample. The loop will be warped (next lesson). Clip length still maxes at 16 bars (FAQ / 1.0.15). Multi-clip record by tapping other slots is 9.5.7. Capture FX automation while recording is 9.5.13."},{"type":"prose","html":"Sound Recognition can still interfere (Troubleshooting). Orange mic icon is expected. Headphones monitoring is now per-track exclusive (9.1.4)."},{"type":"prose","html":"{type:'gap'} Punch-in, count-in for audio (beyond empty-Set metronome changes), and bit-depth of the recorded clip are not specified. Record, stop, play."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Select the Audio track. Enable monitoring on that track only.","From Session View or the track/empty-clip view, start recording a loop.","Perform a phrase (voice, room, interface). Stop.","Launch the new clip. Confirm it loops in Session View.","Record a second take from the other view (session vs track) so you have used both.","Recite: 2.0.1 records audio loops in session or track view."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where can you record audio loops? <strong>Answer:</strong> Session view or track view (RN 2.0.1).","What kind of clip do you get? <strong>Answer:</strong> An audio loop on an Audio track, not a Drum pad sample.","What is the clip length cap? <strong>Answer:</strong> 16 bars."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 Audio Tracks &amp; Recording; Input Monitoring","Note FAQ (16-bar clips)","Troubleshooting Audio Output on Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Record one 2- or 4-bar audio loop you will warp-test in 9.5.4."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-3</code></em>"}]}],"minutes":8},{"id":"note-l9-5-4","title":"9.5.4 — Warped loops: tempo vs pitch independent","blocks":[{"type":"step","title":"9.5.4 — Warped loops: tempo vs pitch independent","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Prove on a 2.0.1 audio clip that tempo and pitch can change independently — the RN warp rule."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1: “Audio loops are warped, so they adapt their tempo without changing the pitch and vice versa.” That sentence is the whole 2.x claim. Change Set tempo (Set Settings slider, ±1, Tap Tempo) and the loop should follow tempo while pitch holds. Use the clip transpose dial (9.5.9) and pitch should change without forcing the old sampler speed coupling."},{"type":"prose","html":"This rule applies to <strong>audio-track loops</strong>, not to Melodic Sampler or Drum Rack. 9.5.5 states the FAQ contrast. Do not write “Note can warp” as a universal sentence."},{"type":"prose","html":"{type:'gap'} Warp modes (Beats, Tones, Complex) are not named in the Note 2.0.1 notes. Do not teach Live warp-mode menus. Teach the independence result only."},{"type":"prose","html":"Clip tempo double/half (9.5.8) is another official tempo control on the clip itself."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Play the audio loop from 9.5.3 at the current Set tempo.","Change Set tempo by a noticeable amount. Listen: timing follows, pitch should hold.","Return tempo. Use the clip <strong>transpose</strong> dial. Listen: pitch moves, tempo should hold.","Write one sentence: “Audio-track loops: tempo and pitch independent (RN 2.0.1).”","Do <strong>not</strong> run the same test on a Sampler pad in this lesson.","Recite the RN sentence from memory."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What does 2.0.1 say about audio loops? <strong>Answer:</strong> They are warped — tempo adapts without changing pitch and vice versa.","Does this apply to every sample in Note? <strong>Answer:</strong> No. Only 2.x audio-track loops. Sampler path is the FAQ rule.","Are Live warp modes documented for Note? <strong>Answer:</strong> {type:'gap'} No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 (audio loops are warped)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Park the Set at a new tempo where the loop still feels like music. Leave transpose at 0 unless the key needs a move."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-4</code></em>"}]}],"minutes":8},{"id":"note-l9-5-5","title":"9.5.5 — Contrast FAQ legacy “warping not available” for pre-2 sampler path","blocks":[{"type":"step","title":"9.5.5 — Contrast FAQ legacy “warping not available” for pre-2 sampler path","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"State both official warp rules, dated, and never blend them into one false sentence."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Two sources disagree if you ignore dates:"},{"type":"list","items":["<strong>FAQ (still published):</strong> “Warping is not currently available in Note.” And: in Sampler or Drum Rack, <strong>Transpose</strong> re-pitches a sample but “also affects the speed of playback. Since Warp is not available in Note, it’s not currently possible to adjust timing and pitch independently.”","<strong>RN 2.0.1:</strong> Audio-track loops <strong>are</strong> warped. Tempo and pitch are independent."],"ordered":false},{"type":"prose","html":"Two dated rules:"},{"type":"list","items":["<strong>Sampler / Drum Rack path = FAQ rule</strong> (including every lesson in 9.2–9.4)","<strong>Audio tracks (2.0+) = RN rule</strong>"],"ordered":false},{"type":"prose","html":"If you are below 2.0.1, only the FAQ rule exists on your device. If you are on 2.0.1+, both paths exist in the same Set. A sliced break on pads will not start warping just because an Audio track sits next to it."},{"type":"prose","html":"The FAQ line is not “wrong” once 2.0.1 ships — it describes the sampler instruments. The RN line is not a stealth delete of the FAQ. Keep the two paths separate."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["On a Melodic Sampler pad, change <strong>Transpose</strong>. Hear speed change with pitch.","Write: “Sampler/Drum Rack: no warp (FAQ).”","On the 2.0.1 audio loop, change Set tempo and clip transpose as in 9.5.4.","Write: “Audio track: warped loops (RN 2.0.1).”","Say both sentences out loud without mixing the subjects.","If you skipped 9.5, only sentence 1 applies. Keep the gap card."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What does the FAQ say about warp? <strong>Answer:</strong> Warping is not currently available; transpose on Sampler/Drum Rack also changes speed.","What does RN 2.0.1 say? <strong>Answer:</strong> Audio loops are warped; tempo and pitch are independent.","Which path uses which rule? <strong>Answer:</strong> Sampler/Drum Rack = FAQ. Audio tracks 2.0+ = RN."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (warp not available; transpose couples speed)","Note Release Notes 2.0.1"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Add both sentences to your session notes. They are the Level 9 honesty test."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-5</code></em>"}]}],"minutes":8},{"id":"note-l9-5-6","title":"9.5.6 — + menu: record or load sample","blocks":[{"type":"step","title":"9.5.6 — + menu: record or load sample","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Use the Session <strong>+</strong> context menu on a 2.0.1 Audio track to either record or load a sample."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1: “Tapping <strong>+</strong> in Session brings up a context menu to record or load a sample.” That menu is the Session-grid door into the same two jobs you already know from samplers — record new audio, or load an existing file — but the destination is an <strong>audio clip</strong>."},{"type":"prose","html":"Load still uses supported formats (WAV, AIFF, M4A, MP3 → WAV) and the 100 MB rule. Loaded loops on this track follow the warp rule (9.5.4), which is why you might load a break here instead of slicing it to pads."},{"type":"prose","html":"{type:'gap'} The note does not list every menu label beyond record or load. Use the two actions you see. Multi-clip record (tap other slots while recording) is the next lesson."},{"type":"prose","html":"Empty audio clip view also has the microphone button for input source (9.1.5). <strong>+</strong> is the Session-grid control."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["On the Audio track, tap <strong>+</strong> in an empty Session slot.","Choose <strong>record</strong> and capture a short loop. Stop.","Tap <strong>+</strong> in another empty slot.","Choose <strong>load</strong> and pick a file from Imported, Recordings, External, or Core Library.","Play both clips. Confirm they are audio clips on this track.","Recite: Session <strong>+</strong> → record or load a sample."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What does <strong>+</strong> in Session open on 2.0.1? <strong>Answer:</strong> A context menu to record or load a sample.","Where does the loaded file go? <strong>Answer:</strong> Onto the Audio track as an audio clip (warped loop).","Does load ignore the 100 MB limit? <strong>Answer:</strong> No. Samples larger than 100 MB cannot be imported or selected."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 (plus menu)","Note FAQ / Working with Samples (formats); RN 1.0.6 (100 MB)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Load one imported loop and record one original loop on the same Audio track, different slots."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-6</code></em>"}]}],"minutes":8},{"id":"note-l9-5-7","title":"9.5.7 — Multi-clip record by tapping other slots","blocks":[{"type":"step","title":"9.5.7 — Multi-clip record by tapping other slots","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"While an audio record is running in Session, tap other clip slots to keep recording new clips without stopping the take."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1: “While recording in session, tap other clip slots to keep recording new clips.” One armed pass, several clips. Use it for verse/chorus takes, or several rooms of the same phrase, without dropping out of record."},{"type":"prose","html":"{type:'gap'} Notes do not say whether you can jump to another track’s slots, or how scene length is decided mid-record. Stay on the Audio track you started. Clip max remains 16 bars. You still have 8 scenes."},{"type":"prose","html":"This is not MIDI Fixed Length <strong>Add</strong>. It is audio Session record. Stop when you have the clips you need. Then pick a keeper and mute or delete extras (long-press clip commands from Level 2)."},{"type":"prose","html":"Monitoring stays exclusive to the track (9.5.12). Do not enable monitor on a second track mid-take."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Start recording an audio loop in Session on the Audio track.","After one phrase, tap the next empty slot on that track. Keep performing.","Tap a third slot if you have something else to say or play.","Stop recording. Launch each new clip.","Keep one, mute or delete the rest.","Recite: while recording in Session, tap other slots to record new clips."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What happens when you tap another slot during Session audio record? <strong>Answer:</strong> Note keeps recording a new clip there (RN 2.0.1).","Do you need to stop between takes? <strong>Answer:</strong> No. That is the point of the feature.","What is the clip length cap still? <strong>Answer:</strong> 16 bars."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 (tap other clip slots while recording)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Record two consecutive scene ideas in one pass. Keep the better clip in scene 1 and the other in scene 2."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-7</code></em>"}]}],"minutes":8},{"id":"note-l9-5-8","title":"9.5.8 — Clip tempo BPM / double / half (audio tracks, 2.0.1)","blocks":[{"type":"step","title":"9.5.8 — Clip tempo BPM / double / half (audio tracks, 2.0.1)","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"On Note <strong>2.0.1+</strong>, change an audio clip’s tempo in BPM and use double/half tempo without treating Sampler as warped."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Check <strong>Settings → Help</strong> first. This module is off-limits on 1.x."},{"type":"prose","html":"Note Release Notes <strong>2.0.1</strong>, Audio Tracks &amp; Recording: you get a “Control to change clip tempo by BPM and double/half tempo.” Audio loops “are warped, so they adapt their tempo without changing the pitch and vice versa.”"},{"type":"prose","html":"That is the opposite of the FAQ sampler rule (7.5.8). Here, tempo and pitch are independent <strong>on the audio track</strong>. Double/half is a clip-tempo move, not a new sample."},{"type":"prose","html":"Add the track with the 2.0.1 <strong>Audio</strong> add-track button (or the + context menu to record/load a sample). Do not load this file into Melodic Sampler if you want independent tempo."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm 2.0.1+ in Help. Add an <strong>Audio</strong> track. Record or load a loop.","Find the clip-tempo control. Change BPM. Confirm pitch stays put.","Use <strong>double</strong> tempo, then <strong>half</strong>. Listen for half-time / double-time, not a chipmunk.","If pitch moved with tempo, you are on a Sampler path — stop and switch to an audio track.","Recite: 2.x audio clip tempo ≠ Sampler Transpose."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which RN added clip tempo BPM and double/half? <strong>Answer:</strong> Note 2.0.1.","Does this apply to Drum Sampler? <strong>Answer:</strong> No. Sampler path still couples pitch and speed (FAQ).","What if Help shows 1.7.x? <strong>Answer:</strong> Skip this module. Update or treat it as a gap."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 (clip tempo; warped audio loops)","Note FAQ (sampler contrast)","https://www.ableton.com/en/release-notes/note/"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Take one 4-bar drum loop on an audio track. Make a half-tempo clip in the next slot. That is a scene change without a new sample."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-8</code></em>"}]}],"minutes":8},{"id":"note-l9-5-9","title":"9.5.9 — Gain and transpose dials; swipe waveform gain (2.0.1)","blocks":[{"type":"step","title":"9.5.9 — Gain and transpose dials; swipe waveform gain (2.0.1)","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Set an audio clip’s <strong>gain</strong> and <strong>transpose</strong> on 2.0.1, including swipe-up/down on the waveform for gain."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1: “Dials for clip gain and transpose.” Also: “Swipe up and down on waveform to change clip gain.” Because audio loops are warped, transpose here is <strong>not</strong> the FAQ Sampler couple — pitch can move while tempo stays (and the reverse)."},{"type":"prose","html":"Sampler still uses sample-tab gain (+24 to −70 dB in Manual §9) and Transpose-with-speed. Do not mix those numbers onto the audio-track dials unless the audio clip UI shows them. {type:'gap'} RN does not publish the audio-track gain range. Use the on-screen dial."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["On a 2.0.1 audio clip, find <strong>gain</strong> and <strong>transpose</strong> dials.","Swipe up/down on the waveform. Confirm gain moves.","Move transpose. Confirm tempo (or loop length feel) does not chipmunk the way Sampler does.","Reset if you have a double-tap/reset on that dial (RN 1.0.15 double-tap reset is documented for parameters/faders; use it if the control offers it).","Recite: swipe waveform = gain; transpose on audio ≠ Sampler speed couple."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How can you change gain without the dial? <strong>Answer:</strong> Swipe up/down on the waveform (RN 2.0.1).","Why is audio-track transpose different from Sampler Transpose? <strong>Answer:</strong> Audio loops are warped (RN). Sampler transpose changes speed (FAQ).","What range is official for audio-track gain? <strong>Answer:</strong> {type:'gap'} RN does not state it. Read the dial."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1","Ableton Note Manual §9 (Sampler gain contrast only)","Note FAQ (sampler path)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Drop a field recording onto an audio track. Set gain so it sits under a Drum Rack, then transpose the audio clip to the Set key."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-9</code></em>"}]}],"minutes":8},{"id":"note-l9-5-10","title":"9.5.10 — Loop brace on audio sections (2.0.1)","blocks":[{"type":"step","title":"9.5.10 — Loop brace on audio sections (2.0.1)","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Use the <strong>loop brace</strong> on a 2.0.1 audio clip to loop a section of the recording."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1: “Loop different sections of a clip via the loop brace.”"},{"type":"prose","html":"The MIDI Editor already uses a loop brace (Manual §8.2.4) to change loop vs clip length, crop, and zoom. 2.0.1 extends loop-brace thinking to <strong>audio</strong> clips: you isolate a hit or a bar inside a longer take without returning to Melodic Sampler crop (1.7.3)."},{"type":"prose","html":"Still 16-bar clip ceiling (FAQ) unless a later RN says otherwise — 2.0.1 does not lift that limit."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Record a take longer than one bar on an audio track (2.0.1 session or track view).","Find the loop brace on the audio clip.","Drag the brace to one bar (or one hit). Play. Confirm only that section loops.","Move the brace to a different section. Play again.","Recite: 2.x audio loop brace = which part of the take repeats."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which RN added audio loop-brace sections? <strong>Answer:</strong> 2.0.1.","Is this Sampler crop? <strong>Answer:</strong> No. Crop/save start/end is 1.7.3 Sample Options. This is the audio clip loop brace.","What length limit still applies to clips? <strong>Answer:</strong> 16 bars (FAQ / Manual)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 (loop brace on audio)","Ableton Note Manual §8.2.4 (loop brace grammar on MIDI — conceptual cousin)","Note FAQ (16-bar clips)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"From one spoken sentence, loop only the last word as a rhythmic chop. That is a section, not a new recording."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-10</code></em>"}]}],"minutes":8},{"id":"note-l9-5-11","title":"9.5.11 — Grid ruler tempo/grid (2.0.1)","blocks":[{"type":"step","title":"9.5.11 — Grid ruler tempo/grid (2.0.1)","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Tap the <strong>grid ruler</strong> on a 2.0.1 audio clip to adjust grid and tempo."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1: “Tap on grid ruler to adjust the grid and tempo.”"},{"type":"prose","html":"That is the official gesture. Combined with clip-tempo BPM / double / half (9.5.8), the ruler is how you line a recorded loop to the Set. Warped audio follows tempo without forced pitch change."},{"type":"prose","html":"{type:'gap'} RN does not list every ruler subdivision. Use the values the UI shows. Do not invent a Live-style warp-marker editor. Note 2.x is not Live’s warp chapter."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["On a 2.0.1 audio clip, tap the <strong>grid ruler</strong>.","Change grid. Play and listen for tighter or looser chop points.","Adjust tempo from that ruler or the clip-tempo control. Confirm pitch independence.","Return to a grid you can actually play to.","Recite: ruler tap = grid and tempo on the audio clip."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What does tapping the grid ruler do? <strong>Answer:</strong> It adjusts the grid and tempo (RN 2.0.1).","Does this create Live warp markers? <strong>Answer:</strong> {type:'gap'} Not documented. Do not teach Live’s warp-marker UI.","Prerequisite version? <strong>Answer:</strong> Note 2.0.1+."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1","Note FAQ (16-bar / version-check Help)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Record a tap-tempo-messy loop, then use the ruler until the downbeats sit with the Drum Rack. Do not bounce to Sampler to “fix” it."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-11</code></em>"}]}],"minutes":8},{"id":"note-l9-5-12","title":"9.5.12 — Input monitoring exclusive per track (2.0.1)","blocks":[{"type":"step","title":"9.5.12 — Input monitoring exclusive per track (2.0.1)","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Enable input monitoring from the <strong>audio track</strong> (or its Session context menu) and treat it as exclusive to that track."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1, Input Monitoring:"},{"type":"list","items":["Audio inputs can be monitored and processed through audio tracks.","Monitoring is enabled from the <strong>audio track view</strong> or the <strong>track context menu in Session</strong>.","It is <strong>exclusive</strong> and <strong>fixed to the track it is enabled on</strong>.","A track-icon indicator shows the input signal in real time.","The <strong>Settings “Input Monitoring” toggle was removed</strong> — monitoring now lives in the Set."],"ordered":false},{"type":"prose","html":"Pre-2.x: Preferences “Monitor Audio Input when headphones are connected” (Manual §2.4.5.2). If you still see that toggle, you are not on 2.0.1. Version-gate."},{"type":"prose","html":"Headphones still matter for latency (Bluetooth KB 34–200 ms). Monitoring a live input on Bluetooth is a bad test."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm 2.0.1+ (Help). Confirm the Settings monitoring toggle is <strong>gone</strong>.","Add an Audio track. Enable monitoring from the track view or Session track menu.","Speak or play into the selected input (mic button on empty audio clip / sampler views — RN).","Confirm the track-icon indicator moves, and another track does <strong>not</strong> also monitor.","Disable monitoring before you leave the lesson so you do not feedback later."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where did monitoring move in 2.0.1? <strong>Answer:</strong> Into the audio track / Session track menu. Settings toggle removed.","Can two tracks monitor at once? <strong>Answer:</strong> RN says exclusive and fixed to the enabled track.","Where do you pick the input source? <strong>Answer:</strong> Microphone button on empty audio clip and sampler views (RN 2.0.1)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 (Input Monitoring; interface inputs)","Ableton Note Manual §2.4.5.2 (pre-2.x contrast)","Bluetooth Headphones and Latency in Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Monitor the built-in mic on one audio track only, then switch the source to an interface input if you have one. Write both source names."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-12</code></em>"}]}],"minutes":8},{"id":"note-l9-5-13","title":"9.5.13 — Capture FX automation while recording (2.0.1)","blocks":[{"type":"step","title":"9.5.13 — Capture FX automation while recording (2.0.1)","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Capture FX automation on an existing clip <strong>or</strong> while recording on a 2.0.1 audio track."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1: “Capture FX Automation on existing clips or automate while recording.”"},{"type":"prose","html":"Manual §7.5 still applies: transport running, dotted line, <strong>Add</strong> commits, solid line stored. 2.0.1 adds that this works in the <strong>audio recording</strong> pass, not only after the clip exists."},{"type":"prose","html":"Also: while recording in Session, tap other clip slots to keep recording new clips (same RN). That is how you grab several takes without stopping the idea."},{"type":"prose","html":"Sampler automation (Level 8) is unchanged. This lesson is the audio-track cousin."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["On 2.0.1, record or load an audio clip. Put an effect on the track (Auto Shift / Erosion are 2.0.1 devices if you have them; otherwise any Track FX).","Press Play. Move an FX knob. Add the automation.","Start a new recording. Move an FX knob <strong>during</strong> the take. Add if the UI offers the same commit.","Play back. Confirm the FX moves without your finger.","Recite: 2.0.1 can automate FX while recording, not only after."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What new automation timing did 2.0.1 add? <strong>Answer:</strong> Automate while recording, plus capture FX automation on existing clips.","Must transport run? <strong>Answer:</strong> Yes for the Manual §7.5 capture grammar. Recording implies running transport.","Name two 2.0.1 FX devices. <strong>Answer:</strong> Auto Shift and Erosion."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1","Ableton Note Manual §7.5"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Record a vocal loop and automate a filter or Auto Shift during take two. Keep take one dry in the slot above."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-13</code></em>"}]}],"minutes":8},{"id":"note-l9-5-14","title":"9.5.14 — Demo Sets that showcase audio tracks (Alice Ivy and others)","blocks":[{"type":"step","title":"9.5.14 — Demo Sets that showcase audio tracks (Alice Ivy and others)","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Open a 2.0.1 demo Set and study how official audio-track content is arranged — do not upload demos to Cloud."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN 2.0.1, Core Library Updates: “Added demo Sets by <strong>Alice Ivy</strong>, <strong>Jose Castillo</strong>, and <strong>Heavy Mellow</strong>. These showcase the newly introduced audio tracks and include new loops and presets.” Also added Auto Shift and Erosion presets."},{"type":"prose","html":"Manual §3.2: Demo Sets appear in the library. RN 1.0.12: Cloud upload of a Demo Set was a bug that got fixed — do not treat demos as your Cloud slots. Cloud holds <strong>eight</strong> Sets (FAQ) and is not backup."},{"type":"prose","html":"Listen, then rebuild one idea with your own audio track. Copying a demo’s arrangement into your working title is study, not theft of the factory file into Cloud."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm 2.0.1+ so the three named demos exist.","Preview (library play button) then open one demo. Count audio vs MIDI tracks.","Find one warped audio loop. Change Set tempo slightly. Confirm it follows (RN warp).","Do <strong>not</strong> Upload to Cloud. Duplicate into a new Set if you want to take it apart.","Write the demo name + Note version in your notes."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Who made the 2.0.1 audio-track demos? <strong>Answer:</strong> Alice Ivy, Jose Castillo, Heavy Mellow.","Why not upload a demo to Cloud? <strong>Answer:</strong> Demos are study files; Cloud has eight slots; RN 1.0.12 fixed demo-upload bugs.","What are the demos for? <strong>Answer:</strong> To showcase audio tracks, new loops, and presets (RN)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 (demo Sets)","Ableton Note Manual §3.2 (Demo Sets in library)","Note FAQ (8 Cloud Sets)","Note Release Notes 1.0.12 (demo Cloud bug)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"After listening, create <strong>+ New</strong> and record one original audio loop. The demo stays in Demo. Your loop is the course Set."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-14</code></em>"}]}],"minutes":8},{"id":"note-l9-5-15","title":"9.5.15 — Audio loop + MIDI drums in one Set (2.0.1)","blocks":[{"type":"step","title":"9.5.15 — Audio loop + MIDI drums in one Set (2.0.1)","blocks":[{"type":"prose","html":"<em>Level 9 · Module 9.5 — Note 2.x audio tracks (version-gated)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Build one scene that combines a <strong>warped audio</strong> loop with a <strong>Drum Rack</strong> MIDI clip under the 8-track / 8-scene limits."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"2.0.1 add-track buttons: <strong>Beat</strong>, <strong>Synth</strong>, and <strong>Audio</strong>. That is the official way to put both kinds of track in one Set. Audio loops warp to Set tempo (RN). Drum Rack stays MIDI + Capture (Manual / Capture KB)."},{"type":"prose","html":"Limits still hold: 8 tracks, 8 scenes, 16-bar clips, 8 Cloud Sets (FAQ). A demo-style sketch is often 2–4 tracks: Beat + Audio + one synth."},{"type":"prose","html":"Link Audio (Note 2.0 / Live 12.4) can send this mix to Live or Push — send only from Note (Link Audio FAQ; Compatibility KB). That is optional."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["<strong>+ New</strong> on 2.0.1. Add <strong>Beat</strong> (or keep the default drum track) and <strong>Audio</strong>.","Capture a 2-bar kit on Drum Rack.","Record or load a warped audio loop. Set clip tempo so it locks to the kit (9.5.8).","Launch both as one scene. Change Set tempo. Confirm audio follows without chipmunk; drums stay MIDI.","Recite: Beat = MIDI kit. Audio = warped loop. Limits unchanged."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which add-track buttons did 2.0.1 add? <strong>Answer:</strong> Beat, Synth, and Audio.","What happens to the audio loop when you change Set tempo? <strong>Answer:</strong> It warps — tempo without forced pitch change (RN).","Can Note receive Link Audio? <strong>Answer:</strong> No. Note and Move send only (Link Audio FAQ)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 2.0.1 (add-track buttons; warped loops)","Note FAQ (limits)","Link Audio FAQ (https://help.ableton.com/hc/en-us/articles/25425913328924)","Note Compatibility KB"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Save this Set locally. It is a candidate hero Set for Level 13.5 (three Cloud slots). Do not upload until you have named it."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l9-5-15</code></em>"}]}],"minutes":8}],"exercises":[]}]};
